import type { BChap } from '../types';
const C: BChap[] = [{"v":["І сказав Господь Мойсеєві у пустелі Синайській, у скинії зібрання, у перший [день] другого місяця, у другий рік після виходу їх із землі Єгипетської, говорячи:","підрахуйте всю громаду синів Ізраїлевих за родами їх, за сімействами їх, за числом імен, усіх чоловічої статі поголовно:","від двадцяти років і вище, усіх придатних для війни у Ізраїля, за ополченнями їх порахуйте їх — ти й Аарон;","з вами повинні бути з кожного коліна по одній людині, яка в роді своєму є головною.","І ось імена чоловіків, що будуть з вами: від Рувима Елицур, син Шедеура;","від Симеона Шелумиїл, син Цуришаддая;","від Іуди Наассон, син Аминадава;","від Іссахара Нафанаїл, син Цуара;","від Завулона Елиав, син Хелона;","від синів Йосифа: від Єфрема Елишама, син Аммиуда; від Манассії Гамалиїл, син Педацура;","від Веніаміна Авидан, син Гидеонія;","від Дана Ахиєзер, син Аммишаддая;","від Асира Пагиїл, син Охрана;","від Гада Елиасаф, син Регуїла;","від Неффалима Ахира, син Енана.","Це — обрані мужі суспільства, начальники колін батьків своїх, глави тисяч Ізраїлевих.","І взяв Мойсей і Аарон мужів, які названі поіменно,","і зібрали вони всю громаду в перший [день] другого місяця. І оголосили вони родоводи свої, за родами їх, за сімействами їх, за числом імен, від двадцяти років і вище, поголовно,","як повелів Господь Мойсеєві. І зробив він підрахунок їм у пустелі Синайській.","І було синів Рувима, первістка Ізраїлевого, за родами їх, за племенами їх, за сімействами їх, за числом імен, поголовно, всіх чоловічої статі, від двадцяти років і вище, усіх придатних для війни,","підраховано в коліні Рувимовому сорок шість тисяч п’ятсот.","Синів Симеона за родами їх, за племенами їх, за сімействами їх, за числом імен, поголовно, всіх чоловічої статі, від двадцяти років і вище, усіх придатних для війни,","підраховано в коліні Симеоновому п’ятдесят дев’ять тисяч триста.","Синів Гада за родами їх, за племенами їх, за сімействами їх, за числом імен [їх, поголовно, всіх чоловічої статі], від двадцяти років і вище, усіх придатних для війни,","підраховано в коліні Гадовому сорок п’ять тисяч шістсот п’ятдесят.","Синів Іуди за родами їх, за племенами їх, за сімействами їх, за числом імен [їх, поголовно, усіх чоловічої статі], від двадцяти років і вище, усіх придатних для війни,","підраховано в коліні Іудиному сімдесят чотири тисячі шістсот.","Синів Іссахара за родами їх, за племенами їх, за сімействами їх, за числом імен [їх, поголовно, усіх чоловічої статі], від двадцяти років і вище, усіх придатних для війни,","підраховано в коліні Іссахаровому п’ятдесят чотири тисячі чотириста.","Синів Завулона за родами їх, за племенами їх, за сімействами їх, за числом імен [їх, поголовно, усіх чоловічої статі], від двадцяти років і вище, усіх придатних для війни,","підраховано в коліні Завулоновому п’ятдесят сім тисяч чотириста.","Синів Йосифа, синів Єфрема за родами їх, за племенами їх, за сімействами їх, за числом імен [їх, поголовно, усіх чоловічої статі], від двадцяти років і вище, усіх придатних для війни,","підраховано в коліні Єфремовому сорок тисяч п’ятсот.","Синів Манассії за родами їх, за племенами їх, за сімействами їх, за числом імен [їх, поголовно, усіх чоловічої статі], від двадцяти років і вище, усіх придатних для війни,","підраховано в коліні Манассіїному тридцять дві тисячі двісті.","Синів Веніаміна за родами їх, за племенами їх, за сімействами їх, за числом імен [їх, поголовно, усіх чоловічої статі], від двадцяти років і вище, усіх придатних для війни,","підраховано в коліні Веніаміновому тридцять п’ять тисяч чотириста.","Синів Дана за родами їх, за племенами їх, за сімействами їх, за числом імен [їх, поголовно, усіх чоловічої статі], від двадцяти років і вище, усіх придатних для війни,","підраховано в коліні Дановому шістдесят дві тисячі сімсот.","Синів Асира за родами їх, за племенами їх, за сімействами їх, за числом імен [їх, поголовно, усіх чоловічої статі], від двадцяти років і вище, усіх придатних для війни,","підраховано в коліні Асировому сорок одна тисяча п’ятсот.","Синів Неффалима за родами їх, за племенами їх, за сімействами їх, за числом імен [їх, поголовно, усіх чоловічої статі], від двадцяти років і вище, усіх придатних для війни,","підраховано в коліні Неффалимовому п’ятдесят три тисячі чотириста.","Ось ті, що ввійшли у підрахунок, яких порахував Мойсей і Аарон і начальники Ізраїля — дванадцять чоловік, по одній людині з кожного племені.","І було всіх, що ввійшли в підрахунок, синів Ізраїлевих, за сімействами їх, від двадцяти років і вище, усіх придатних для війни в Ізраїлі,","і було всіх, що ввійшли у підрахунок шістсот три тисячі п’ятсот п’ятдесят.","А левити за поколіннями батьків їх не були пораховані між ними.","І сказав Господь Мойсеєві, говорячи:","тільки коліна Левія не внось у перепис, і не враховуй їх разом із синами Ізраїля;","але доручи левитам скинію одкровення і все приладдя її і все, що при ній; нехай вони носять скинію і все приладдя її, і служать при ній, і біля скинії нехай ставлять стан свій;","і коли потрібно переносити скинію, нехай піднімають її левити; і коли потрібно зупинитися скинії, нехай ставлять її левити; а якщо приступить хто сторонній, відданий буде на смерть.","Сини Ізраїлеві повинні ставати кожен у стані своєму і кожен при своєму прапорі, за ополченнями своїми;","а левити повинні ставити стан біля скинії одкровення, щоб не було гніву на громаду синів Ізраїлевих, і будуть левити стояти на сторожі при скинії одкровення.","І зробили сини Ізраїлеві; як повелів Господь Мойсеєві, так вони і зробили."],"x":{"1":"1.25.22","2":"1.30.12","3":"3.26.4|12.25.28|13.25.5","4":"3.13.4","6":"3.10.19","7":"3.10.14|12.2.10","10":"3.2.18:20","11":"3.2.22","12":"3.2.25","13":"3.2.27","14":"3.2.14","15":"3.2.29","19":"3.26.64","46":"3.26.51","49":"3.3.15","51":"3.3.10:38|3.4.5|3.18.7","54":"1.12.28|3.2.34"}},{"v":["І сказав Господь Мойсеєві й Аарону, говорячи:","сини Ізраїлеві повинні кожен ставити стан свій при прапорі своєму, при знаках сімейств своїх; перед скинією зібрання навколо повинні ставити стан свій.","З передньої сторони на схід ставлять стан: прапор стану Іудиного за ополченнями їх, і начальник синів Іуди Наассон, син Аминадава,","і воїнства його, що увійшли у підрахунок його, сімдесят чотири тисячі шістсот;","після нього ставить стан коліно Іссахарове, і начальник синів Іссахара Нафанаїл, син Цуара,","і воїнства його, що увійшли у підрахунок його, п’ятдесят чотири тисячі чотириста;","[далі ставить стан] коліно Завулона, і начальник синів Завулона Елиав, син Хелона,","і воїнства його, що увійшли у підрахунок його, п’ятдесят сім тисяч чотириста;","всіх, що увійшли у підрахунок до стану Іуди, сто вісімдесят шість тисяч чотириста, за ополченнями їх; першими вони повинні вирушати.","Прапор стану Рувимового на південь, за ополченнями їх, і начальник синів Рувима Елицур, син Шедеура,","і воїнства його, що увійшли у підрахунок його, сорок шість тисяч п’ятсот;","поряд нього ставить стан коліно Симеонове, і начальник синів Симеона Шелумиїл, син Цуришаддая,","і воїнства його, що увійшли у підрахунок його, п’ятдесят дев’ять тисяч триста;","потім коліно Гада, і начальник синів Гада Елиасаф, син Регуїла,","і воїнства його, що увійшли у підрахунок його, сорок п’ять тисяч шістсот п’ятдесят;","усіх, що увійшли у підрахунок до стану Рувима, сто п’ятдесят одна тисяча чотириста п’ятдесят, за ополченнями їх; другими вони повинні вирушати.","Коли піде скинія зібрання, стан левитів буде в середині станів. Як стоять, так і повинні йти, кожен на своєму місці при прапорах своїх.","Прапор стану Єфремового за ополченнями їх на захід, і начальник синів Єфрема Елишама, син Аммиуда,","і воїнства його, що увійшли у підрахунок його, сорок тисяч п’ятсот;","поряд нього коліно Манассіїне, і начальник синів Манассії Гамалиїл, син Педацура,","і воїнства його, що ввійшли у підрахунок його, тридцять дві тисячі двісті;","потім коліно Веніаміна, і начальник синів Веніаміна Авидан, син Гидеонія,","і воїнства його, що ввійшли у підрахунок його, тридцять п’ять тисяч чотириста;","усіх, що увійшли у підрахунок до стану Єфрема, сто вісім тисяч сто, за ополченнями їх; третіми вони повинні вирушати.","Прапор стану Данового на північ, за ополченнями їх, і начальник синів Дана Ахиєзер, син Аммишаддая,","і воїнства його, що ввійшли у підрахунок його, шістдесят дві тисячі сімсот;","поряд нього ставить стан коліно Асирове, і начальник синів Асира Пагиїл, син Охрана,","і воїнства його, що увійшли у підрахунок його, сорок одна тисяча п’ятсот;","далі [ставить стан] коліно Неффалима, і начальник синів Неффалима Ахира, син Енана,","і воїнства його, що ввійшли у підрахунок його, п’ятдесят три тисячі чотириста;","усіх, що увійшли у підрахунок до стану Дана, сто п’ятдесят сім тисяч шістсот; вони повинні йти останніми при прапорах своїх.","Ось ті, що увійшли у підрахунок, сини Ізраїля за сімействами їх. Усіх, що увійшли у підрахунок у станах, за ополченнями їх, шістсот три тисячі п’ятсот п’ятдесят.","А левити не увійшли у підрахунок разом із синами Ізраїля, як повелів Господь Мойсеєві.","І зробили сини Ізраїлеві все, що повелів Господь Мойсею: так ставали станами при прапорах своїх і так ішли кожен за племенами своїми, за сімействами своїми."],"x":{"3":"3.10.5","5":"3.10.15","7":"3.10.16","10":"3.10.6","12":"3.10.19","14":"3.10.20","17":"25.45.6","18":"25.79.3|3.10.22","20":"3.1.10","22":"3.1.11|3.7.60|3.10.24","34":"1.12.28|2.24.23"}},{"v":["Ось родовід Аарона і Мойсея, коли говорив Господь Мойсеєві на горі Синаї,","і ось імена синів Аарона: первісток Надав, Авиуд, Єлеазар та Іфамар;","це імена синів Аарона, священиків, помазаних, яких він посвятив, аби священнодіяти;","але Надав і Авиуд померли перед лицем Господа, коли вони принесли вогонь чужий перед лице Господа в пустелі Синайській, дітей же в них не було; і залишилися священиками Єлеазар та Іфамар при Аароні, батькові своєму.","І сказав Господь Мойсеєві, говорячи:","приведи коліно Левія, і постав його перед Аароном священиком, щоб вони служили йому;","і нехай вони будуть на варті за нього й на варті за всю громаду при скинії зібрання, щоб відправляти служби при скинії;","і нехай зберігають усі речі скинії зібрання, і будуть на варті за синів Ізраїлевих, щоб відправляти служби при скинії;","віддай левитів Аарону [братові твоєму] і синам його [священикам] у розпорядження: нехай будуть вони віддані йому з синів Ізраїлевих;","Аарону ж і синам його доручи [скинію одкровення], щоб вони пильнували священичі обов’язки свої [і все, що при жертовнику і за завісою]; а якщо приступить хто сторонній, відданий буде на смерть.","І сказав Господь Мойсеєві, говорячи:","ось, Я взяв левитів із синів Ізраїлевих замість усіх первістків, що розкривають утробу, з синів Ізраїлевих [вони будуть замість них]; левити повинні бути Мої,","бо всі первістки — Мої; у той день, коли уразив Я всіх первістків у землі Єгипетській, освятив Я Собі всіх первістків Ізраїлевих від людини до худоби; вони повинні бути Мої. Я Господь.","І сказав Господь Мойсеєві в пустелі Синайській, говорячи:","підрахуй синів Левія за сімействами їх, за родами їх; усіх чоловічої статі від одного місяця і вище підрахуй.","І полічив їх Мойсей [і Аарон] за словом Господнім, як наказано.","І ось сини Левія за іменами їх: Гирсон, Кааф і Мерарі.","І ось імена синів Гирсонових за родами їх: Ливні і Шимей.","І сини Каафа за родами їх: Амрам та Іцгар, Хеврон та Узиїл.","І сини Мерарі за родами їх: Махлі й Муші. Ось роди Левія за сімействами їх.","Від Гирсона рід Ливні й рід Шимея: це роди Гирсонові.","Підрахованих було всіх чоловічої статі, від одного місяця і вище, сім тисяч п’ятсот.","Роди Гирсонові повинні ставати станом позаду скинії на захід;","начальник покоління синів Гирсонових Елиасаф, син Лаелів;","синам Гирсоновим при скинії зібрання доручаються охорона скинії й покрову її, і завіса до входу в скинію зібрання,","і завіси двору і завіса входу до двору, що навколо скинії й жертовника, і шнури її, з усіма їх приладдям.","Від Каафа рід Амрама й рід Іцгара, й рід Хеврона, і рід Узиїла: це роди Каафа.","За підрахунком усіх чоловічої статі, від одного місяця і вище, вісім тисяч шістсот, які охороняли святилище.","Роди синів Каафових повинні ставити стан свій на південному боці скинії;","начальник же покоління родів Каафових Елцафан, син Узиїла;","під їх охороною ковчег, стіл, світильник, жертовники, священні сосуди, які вживаються при служінні, і завіса з усім приладдям її.","Начальник над начальниками левитів Єлеазар, син Аарона священика; під його наглядом ті, яким ввірена охорона святилища.","Від Мерарі рід Махлі й рід Муші: це роди Мерарі;","підрахованих за числом усіх чоловічої статі, від одного місяця й вище — шість тисяч двісті;","начальник покоління родів Мерарі Цуриїл, син Авихаїла; вони повинні ставити стан свій на північній стороні скинії;","охороні синів Мерарі доручаються бруси скинії і жердини її, і стовпи її, і підніжжя її і всі речі її, з усім обладнанням їх,","і стовпи двору з усіх боків і підніжжя їх і кілки їх і шнури їх.","А з передньої сторони скинії, на схід перед скинією зібрання, повинні ставити стан Мойсей і Аарон і сини його, яким довірено охорону святилища за синів Ізраїлевих; а якщо приступить хто сторонній, відданий буде на смерть.","Усіх підрахованих левитів, яких підрахували Мойсей і Аарон за велінням Господнім, за родами їх, усіх чоловічої статі, від одного місяця й вище, двадцять дві тисячі.","І сказав Господь Мойсеєві: підрахуй усіх первістків чоловічої статі з синів Ізраїлевих, від одного місяця і вище, і перелічи їх поіменно;","і візьми левитів для Мене, — Я Господь, — замість усіх первістків із синів Ізраїля, а худобу левитів замість усієї первородної худоби синів Ізраїлевих.","І підрахував Мойсей, як повелів йому Господь, усіх первістків із синів Ізраїлевих","і було всіх первістків чоловічої статі, за числом імен, від одного місяця і вище, двадцять дві тисячі двісті сімдесят три.","І сказав Господь Мойсеєві, говорячи:","візьми левитів замість усіх первістків із синів Ізраїля і худобу левитів замість худоби їх; нехай левити будуть Мої. Я Господь.","А для викупу двохсот сімдесяти трьох, які зайві проти числа левитів, з первістків Ізраїлевих,","візьми по п’ять сиклів за людину, за сиклем священним візьми, двадцять гер у сиклі,","і віддай срібло це Аарону і синам його, на викуп за зайвих проти числа їх.","І взяв Мойсей срібло викупу за зайвих проти числа замінених левитами,","від первістків Ізраїлевих узяв срібла тисячу триста шістдесят п’ять [сиклів], за сиклем священним,","і віддав Мойсей срібло викупу [за зайвих] Аарону і синам його за словом Господнім, як повелів Господь Мойсеєві."],"x":{"2":"1.6.23|12.24.1","3":"2.8.2|1.28.41","4":"2.10.1|3.26.61|12.24.2","6":"14.6.18","8":"2.8.35","9":"3.8.19","10":"3.16.40|3.18.7","12":"1.29.24|3.8.16","13":"1.13.2|1.22.29|1.34.19|2.27.26|3.8.17|52.2.23","17":"0.46.11|1.6.16|3.26.57|12.6.1","19":"1.6.18|3.26.58-59","30":"1.6.22|2.10.4","31":"3.7.9","32":"12.9.11|3.19.3|11.25.18","38":"3.1.51|3.16.40|3.18.7","47":"3.18.16|1.30.13"}},{"v":["І сказав Господь Мойсеєві й Аарону, говорячи:","підрахуй синів Каафових із синів Левія за родами їх, за сімействами їх,","від тридцяти років і вище до п’ятдесяти років, усіх здатних до служби, щоб відправляти роботи в скинії зібрання.","Ось служіння синів Каафових [левитів за родами їх, за сімействами їх,] у скинії зібрання: носити Святе Святих.","Коли стану потрібно вирушити в дорогу, Аарон і сини його ввійдуть, і знімуть завісу, що закриває, і покриють нею ковчег одкровення;","і покладуть на неї покров зі шкір синього кольору, і поверх його накинуть покривало все з блакитної вовни, і вкладуть жердини його;","і стіл хлібів предкладення накриють одежею з блакитної вовни, і поставлять на ньому блюда, тарілки, чаші і кружки для узливання, і хліб його повсякчасний повинен бути на ньому;","і покладуть на них одяг багряний, і покриють її покровом зі шкіри синього кольору, і вкладуть жердини його;","і візьмуть одяг з блакитної вовни, і покриють світильник і лампади його, і щипці його, і лотки його, і всі сосуди для єлею, які вживаються при ньому,","і покриють його та все приладдя його покровом зі шкір синіх, і покладуть на носилки;","і на золотий жертовник покладуть одяг з блакитної вовни, і покриють його покровом зі шкір синіх, і вкладуть жердини його.","І візьмуть усі речі службові, які вживаються для служіння у святилищі, і покладуть в одежу з блакитної вовни, і покриють їх покровом зі шкір синіх, і покладуть на носилки.","І очистять жертовник від попелу і накриють його одежею пурпуровою;","і покладуть на його всі сосуди його, які вживаються для служіння при ньому — вугільниці, виделки, лопатки і чаші, всі сосуди жертовника — і покриють його покровом зі шкір синіх, і вкладуть жердини його. [І візьмуть пурпуровий одяг, і покриють умивальник і підніжжя його, і покладуть на них шкіряне синє покривало, і поставлять на носилки.]","Коли, при відправленні стану в дорогу, Аарон і сини його покриють усе святилище і всі речі святилища, тоді сини Каафа підійдуть, щоб нести; але не повинні вони доторкатися до святилища, щоб не вмерти. Ці частини скинії зібрання повинні носити сини Каафові.","Єлеазару, сину Аарона священика, доручається єлей для світильника і запашне кадіння, і повсякчасне хлібне приношення і єлей помазання, — доручається вся скинія та все, що в ній, святилище і приладдя його.","І сказав Господь Мойсеєві й Аарону, говорячи:","не погубіть коліна племен Каафових із середовища левитів,","але ось що зробіть їм, щоб вони були живі й не померли, коли приступають до Святого Святих: Аарон і сини його нехай прийдуть і поставлять їх кожного на служіння його й біля ноші його;","але самі вони не повинні підходити дивитися святиню, коли покривають її, щоб не померти.","І сказав Господь Мойсеєві, говорячи:","підрахуй і синів Гирсона за сімействами їх, за родами їх,","від тридцяти років і вище до п’ятдесяти років, підрахуй їх усіх здатних до служби, щоб виконувати роботи при скинії зібрання.","Ось роботи сімейств Гирсонових, в їх служінні й носінні важкої ваги:","вони повинні носити покрови скинії і скинію зібрання, і покров її, і покров шкіряний синій, який поверх нього, і завісу входу до скинії зібрання,","і завіси двору, і завісу входу до двору, що навколо скинії і жертовника, і шнури їх, і всі речі, що належать до них; і все, що робиться при них, вони повинні працювати;","за наказом Аарона і синів його повинні виконуватися всі служби синів Гирсонових при всякому носінні важких речей і всякій роботі їхній, і доручіть їм охороняти все, що вони носять;","ось служби родів синів Гирсонових у скинії зібрання, і ось що доручається їх охороні під наглядом Іфамара, сина Аарона, священика.","Синів Мерариних за родами їх, за сімействами їх порахуй,","від тридцяти років і вище до п’ятдесяти років, порахуй усіх здатних до служби, щоб виконувати роботи при скинії зібрання.","Ось що вони повинні носити за службою їх при скинії зібрання: бруси скинії і жердини її, і стовпи її і підніжжя її,","і стовпи двору з усіх боків і підніжжя їх, і кілки їх, і шнури їх, і всі речі при них і все приладдя їх; і поіменно порахуйте речі, які вони зобов’язані носити;","ось роботи родів синів Мерариних, за службою їх при скинії зібрання, під наглядом Іфамара, сина Аарона, священика.","І порахували Мойсей і Аарон і начальники громади синів Каафових за родами їх і за сімействами їх,","від тридцяти років і вище до п’ятдесяти років, усіх здатних до служби, для робіт у скинії зібрання;","і були підраховані, за родами їх, дві тисячі сімсот п’ятдесят:","це — підраховані з родів Каафових, усі службовці при скинії зібрання, яких порахував Мойсей і Аарон за повелінням Господнім, даним через Мойсея.","І полічені сини Гирсона за родами їх і за сімействами їх,","від тридцяти років і вище до п’ятдесяти років, усі здатні до служби, для робіт у скинії зібрання;","і були пораховані за родами їх, за сімействами їх, дві тисячі шістсот тридцять:","це — пораховані з родів синів Гирсона, усі службовці при скинії зібрання, яких полічив Мойсей і Аарон, за повелінням Господнім,","І пораховані роди синів Мерариних за родами їх, за сімействами їх,","від тридцяти років і вище до п’ятдесяти років, усі здатні до служби, для робіт при скинії зібрання;","і були полічені за родами їх, [за сімействами їх,] три тисячі двісті:","це — підраховані з родів синів Мерариних, яких порахував Мойсей і Аарон за повелінням Господнім, даним через Мойсея.","І підраховані всі левити, яких порахував Мойсей і Аарон і начальники Ізраїля за родами їх і за сімействами їх,","від тридцяти років і вище до п’ятдесяти років, усі здатні до служби для робіт і ношення у скинії зібрання;","і було підраховано їх вісім тисяч п’ятсот вісімдесят;","за повелінням Господнім через Мойсея призначені вони кожен до своєї роботи і носіння, і пораховані, як повелів Господь Мойсеєві."],"x":{"3":"3.8.15","5":"3.10.17|5.18.1","6":"10.8.8","7":"1.25.30","9":"1.25.31","11":"1.30.3","14":"1.27.3","15":"12.13.10","16":"1.30.23","20":"8.6.19","24":"12.15.2","25":"1.26.7:14","28":"3.7.7","31":"3.10.17|1.26.15","33":"3.7.8"}},{"v":["І сказав Господь Мойсеєві, говорячи:","повели синам Ізраїлевим вислати зі стану всіх прокажених, і всіх, хто має течу, і всіх, що осквернилися від мертвого,","і чоловіків і жінок вишліть, за стан вишліть їх, щоб не оскверняли вони станів своїх, серед яких Я живу.","І зробили так сини Ізраїлеві, і вислали їх вони зі стану; як говорив Господь Мойсеєві, так і зробили сини Ізраїлеві.","І сказав Господь Мойсеєві, говорячи:","скажи синам Ізраїлевим: якщо чоловік або жінка вчинить який-небудь гріх проти людини, і через це зробить злочин проти Господа, і винна буде душа та,","то нехай сповідаються у гріху своєму, який вони вчинили, і повернуть повністю те, в чому винні, і додадуть до того п’яту частину і віддадуть тому, проти кого згрішили;","якщо ж у нього немає спадкоємця, якому слід було б повернути за провину: то присвятити це Господу; нехай буде це священикові, зверх барана очищення, яким він очистить його;","й усяке возношення з усіх святинь синів Ізраїлевих, які вони приносять до священика, належить йому,","і посвячене ким-небудь належить йому; все, що дасть хто священикові, йому належить.","І сказав Господь Мойсеєві, говорячи:","оголоси синам Ізраїлевим і скажи їм: якщо зрадить кого дружина, і порушить вірність до нього,","і переспить хто з нею і виллє сім’я, і це буде приховано від очей чоловіка її, і вона оскверниться таємно, і не буде на неї свідка, і не буде викрита,","і найде на нього дух ревнощів, і буде ревнувати дружину свою, коли вона осквернена, або зійде на нього дух ревнощів, і він буде ревнувати дружину свою, коли вона не осквернена, —","нехай приведе чоловік дружину свою до священика і принесе за неї в жертву десяту частину ефи ячмінного борошна, але не зливає на нього єлею і не кладе ливану, тому що це приношення ревнощів, приношення спомину, що нагадує про беззаконня;","а священик нехай приведе і поставить її перед лице Господнє,","і візьме священик святої води у глиняну посудину, і візьме священик землі з підлоги скинії і покладе у воду;","і поставить священик дружину перед лице Господнє, і відкриє голову дружини, і дасть їй у руки приношення спомину, — це приношення ревнощів, в руці ж у священика буде гірка вода, що наводить прокляття.","І закляне її священик і скаже дружині: якщо ніхто не переспав з тобою, і ти не осквернилася і не зрадила чоловіка свого, то непошкоджена будеш від цієї гіркої води, що наводить прокляття;","але якщо ти зрадила чоловіка твого й осквернилася, і якщо хто переспав з тобою, крім чоловіка твого, —","тоді священик нехай закляне дружину клятвою прокляття і скаже священик дружині: нехай піддасть тебе Господь прокляттю і клятві в народі твоєму, і нехай зробить Господь лоно твоє опалим і живіт твій опухлим;","і нехай пройде вода ця, що наводить прокляття, у нутрощі твої, щоб опух живіт [твій] і опало лоно [твоє]. І скаже дружина: амінь, амінь.","І напише священик заклинання ці на сувої, і змиє їх у гірку воду;","і дасть дружині випити гірку воду, що наводить прокляття, і ввійде в неї вода, що наводить прокляття, на шкоду їй.","І візьме священик з рук дружини хлібне приношення ревнощів, і піднесе це приношення перед Господом, і віднесе його до жертовника;","і візьме священик жменею з хлібного приношення частину в пам’ять, і спалить на жертовнику, і потім дасть дружині випити води;","і коли напоїть її водою, тоді, якщо вона нечиста і зробила злочин проти чоловіка свого, гірка вода, що наводить прокляття, ввійде в неї, на шкоду їй, і опухне утроба її й опаде лоно її, і буде ця дружина проклятою в народі своєму;","якщо ж дружина не осквернилася і була чиста, то залишиться неушкодженою і буде запліднена сіменем.","Ось закон про ревнощі, коли дружина зрадить чоловіка свого й оскверниться,","або коли на чоловіка найде дух ревнощів, і він буде ревнувати дружину свою, тоді нехай він поставить дружину перед лицем Господа, і зробить з нею священик усе за цим законом, —","і буде чоловік чистим від гріха, а дружина понесе на собі гріх свій."],"x":{"2":"2.13.46|2.15.2","3":"3.12.15","6":"2.6.2","7":"52.19.8","8":"2.6.6","9":"1.29.28","14":"30.9.1","15":"1.16.36","17":"1.30.18|1.32.20","18":"63.11.5-6","21":"32.42.18|32.44.12","22":"4.27.15"}},{"v":["І сказав Господь Мойсеєві, говорячи:","оголоси синам Ізраїлевим і скажи їм: якщо чоловік або жінка зважиться дати обітницю назорейства, щоб посвятити себе в назореї Господу,","то він повинен утриматися від вина і міцного напою, і не повинен вживати ні оцту з вина, ні оцту з напою, і нічого виготовленого із винограду не повинен пити, і не повинен їсти ні сирих, ні сушених виноградних ягід;","у всі дні назорейства свого не повинен він їсти [і пити] нічого, що виготовляється із винограду, від зерен до шкірки.","В усі дні обітниці назорейства його бритва не повинна доторкатися до голови його; до закінчення днів, на які він посвятив себе в назореї Господу, святий він: повинний ростити волосся на голові своїй.","В усі дні, на які він посвятив себе в назореї Господу, не повинен він підходити до мертвого тіла:","доторканням до батька свого, і матері своєї, і брата свого, і сестри своєї, не повинен він осквернятися, коли вони помруть, тому що посвята Богу його на чоло його;","в усі дні назорейства свого святий він Господу.","Якщо ж помре при ньому хто-небудь раптово, ненавмисне, і він осквернить тим голову назорейства свого: то він повинен обстригти голову свою в день очищення його, у сьомий день повинен обстригти її,","й у восьмий день повинен принести двох горлиць, або двох молодих голубів, до священика, до входу в скинію зібрання;","священик одного з птахів принесе в жертву за гріх, а іншого у всепалення, і очистить його від осквернення мертвим тілом, і освятить голову його в той день;","і повинен він знову почати присвячені Господу дні назорейства свого і принести однолітнього агнця в жертву за провину; попередні ж дні пропали, тому що назорейство його осквернене.","І ось закон про назорея, коли виповняться дні назорейства його: слід привести його до входу в скинію зібрання,","і він принесе в жертву Господу одного однолітнього агнця без вад у всепалення, і одну однолітню агницю без вад в жертву за гріх, і одного барана без вад у жертву мирну,","і кошик опрісноків із пшеничного борошна, хлібів, спечених з єлеєм, і прісних коржів, помазаних єлеєм, і при них хлібне приношення й узливання;","і представить це священик перед Господом, і принесе жертву його за гріх і всепалення його;","барана принесе в жертву мирну Господу з кошиком опрісноків, також зробить священик хлібне приношення його й узливання його;","і обстриже назорей при вході в скинію зібрання голову назорейства свого, і візьме волосся голови назорейства свого, і покладе на вогонь, що під мирною жертвою;","і візьме священик зварене плече барана й один прісний пиріг з кошика й один прісний корж, і покладе на руки назорею, після того, як обстриже він голову назорейства свого;","і піднесе це священик, потрясаючи перед Господом: ця святиня — для священика, зверх грудей потрясання і зверх плеча возношення. Після цього назорей може пити вино.","Ось закон про назорея, який дав обітницю, і жертва його Господу за назорейство своє, крім того, що дозволить йому достаток його; за обітницею своєю, яку він дасть, так і повинен він чинити, зверх узаконеного про назорейство його.","І сказав Господь Мойсеєві, говорячи:","скажи Аарону і синам його: так благословляйте синів Ізраїлевих, говорячи їм:","нехай благословить тебе Господь і збереже тебе!","нехай зглянеться на тебе Господь світлим лицем Своїм і помилує тебе!","нехай зверне Господь лице Своє на тебе і дасть тобі мир!","Так нехай закликають ім’я Моє на синів Ізраїлевих, і Я [Господь] благословлю їх."],"x":{"2":"6.13.5|8.1.11|32.1.5","5":"6.13.5","7":"2.21.2:11","10":"2.12.8|2.14.22","18":"54.21.24","20":"1.29.27|2.7.31","23":"30.36.18","24":"25.66.8","25":"25.4.7","26":"25.4.7","27":"30.50.23"}},{"v":["Коли Мойсей поставив скинію, і помазав її, і освятив її і все приладдя її, і жертовник і усе приладдя його, і помазав їх і освятив їх,","тоді прийшли [дванадцять] начальників Ізраїлевих, глави сімейств їх, начальники колін, що завідували підрахунком,","і представили приношення своє перед Господом, шість критих возів і дванадцять волів, по одному возу від двох начальників і по одному волу від кожного, і представили це перед скинією.","І сказав Господь Мойсеєві, говорячи:","візьми від них; це буде для виконання робіт при скинії зібрання; і віддай це левитам, дивлячись за родом служби їх.","І взяв Мойсей вози і волів, і віддав їх левитам:","два вози і чотирьох волів віддав синам Гирсоновим, за родом служби їх:","і чотири вози і вісім волів віддав синам Мерариним, за родом служб їх, під наглядом Іфамара, сина Аарона, священика;","а синам Каафовим не дав, тому що служба їх — носити святилище; на плечах вони повинні носити.","І принесли начальники жертви освячення жертовника в день помазання його, і представили начальники приношення своє перед жертовником.","І сказав Господь Мойсеєві: по одному начальнику на день нехай приносять приношення своє для освячення жертовника.","В перший день приніс приношення своє Наассон, син Аминадавів, від коліна Іудиного;","приношення його було: одне срібне блюдо, вагою в сто тридцять сиклів, одна срібна чаша в сімдесят сиклів, за сиклем священним, наповнені пшеничним борошном, змішаним з єлеєм, для приношення хлібного,","одна золота кадильниця у десять сиклів, наповнена курінням,","один телець, один баран, один однолітній агнець, для всепалення,","один козел у жертву за гріх,","і в жертву мирну два воли, п’ять баранів, п’ять козлів, п’ять однолітніх агнців; ось приношення Наассона, сина Аминадавового.","На другий день приніс Нафанаїл, син Цуара, начальник [коліна] Іссахарового;","він приніс від себе приношення: одне срібне блюдо, вагою в сто тридцять сиклів, одну срібну чашу в сімдесят сиклів, за сиклем священним, наповнені пшеничним борошном, змішаним з єлеєм, для приношення хлібного,","одну золоту кадильницю в десять сиклів, наповнену курінням,","одного тельця, одного барана, одного однолітнього агнця, у всепалення,","одного козла в жертву за гріх,","і в жертву мирну двох волів, п’ять баранів, п’ять козлів, п’ять однолітніх агнців; ось приношення Нафанаїла, сина Цуарового.","В третій день начальник синів Завулонових Елиав, син Хелона;","приношення його: одне срібне блюдо, вагою в сто тридцять сиклів, одна срібна чаша в сімдесят сиклів, за сиклем священним, наповнені пшеничним борошном, змішаним з єлеєм, для приношення хлібного,","одна золота кадильниця в десять сиклів, наповнена курінням,","один телець, один баран, один однолітній агнець, у всепалення,","один козел у жертву за гріх,","і в жертву мирну два воли, п’ять баранів, п’ять козлів, п’ять однолітніх агнців; ось приношення Елиава, сина Хелонового.","В четвертий день начальник синів Рувимових Елицур, син Шедеурів;","приношення його: одне срібне блюдо, вагою в сто тридцять сиклів, одна срібна чаша в сімдесят сиклів, за сиклем священним, наповнені пшеничним борошном, змішаним з єлеєм, для приношення хлібного,","одна золота кадильниця в десять сиклів, наповнена курінням,","один телець, один баран, один однолітній агнець, у всепалення,","один козел у жертву за гріх,","і в жертву мирну два воли, п’ять баранів, п’ять козлів і п’ять однолітніх агнців; ось приношення Елицура, сина Шедеурового.","У п’ятий день начальник синів Симеонових Шелумиїл, син Цуришаддая;","приношення його: одне срібне блюдо, вагою в сто тридцять сиклів, одна срібна чаша в сімдесят сиклів, за сиклем священним, наповнені пшеничним борошном, змішаним з єлеєм, для приношення хлібного,","одна золота кадильниця в десять сиклів, наповнена курінням,","один телець, один баран, один однолітний агнець, у всепалення,","один козел у жертву за гріх,","і в жертву мирну два воли, п’ять баранів, п’ять козлів і п’ять однолітніх агнців; ось приношення Шелумиїла, сина Цуришаддаєвого.","В шостий день начальник синів Гадових Елиасаф, син Регуїла;","приношення його: одне срібне блюдо, вагою в сто тридцять сиклів, одна срібна чаша в сімдесят сиклів, за сиклем священним, наповнені пшеничним борошном, змішаним з єлеєм, для приношення хлібного,","одна золота кадильниця в десять сиклів, наповнена курінням,","один телець, один баран, один однолітній агнець, у всепалення,","один козел у жертву за гріх,","і в жертву мирну два воли, п’ять баранів, п’ять козлів і п’ять однолітніх агнців; ось приношення Елиасафа, сина Регуїлового.","У сьомий день начальник синів Єфремових Елишама, син Аммиуда.","Приношення його: одне срібне блюдо, вагою в сто тридцять сиклів, одна срібна чаша в сімдесят сиклів, за сиклем священним, наповнені пшеничним борошном, змішаним з єлеєм, для приношення хлібного,","одна золота кадильниця в десять сиклів, наповнена курінням,","один телець, один баран, один однолітний агнець, у всепалення,","один козел у жертву за гріх,","і в жертву мирну два воли, п’ять баранів, п’ять козлів, п’ять однолітніх агнців; ось приношення Елишами, сина Аммиудового.","У восьмий день начальник синів Манассіїних Гамалиїл, син Педацура.","Приношення його: одне срібне блюдо, вагою в сто тридцять сиклів, одна срібна чаша в сімдесят сиклів, за сиклем священним, наповнені пшеничним борошном, змішаним з єлеєм, для приношення хлібного,","одна золота кадильниця в десять сиклів, наповнена курінням,","один телець, один баран, один однолітній агнець, у всепалення,","один козел у жертву за гріх,","і в жертву мирну два воли, п’ять баранів, п’ять козлів, п’ять однолітніх агнців; ось приношення Гамалиїла, сина Педацурового.","В дев’ятий день начальник синів Веніамінових Авидан, син Гидеонія;","приношення його: одне срібне блюдо, вагою в сто тридцять сиклів, одна срібна чаша в сімдесят сиклів, за сиклем священним, наповнені пшеничним борошном, змішаним з єлеєм, для приношення хлібного,","одна золота кадильниця в десять сиклів, наповнена курінням,","один телець, один баран, один однолітній агнець, у всепалення,","один козел в жертву за гріх,","й у жертву мирну два воли, п’ять баранів, п’ять козлів, п’ять однолітніх агнців; ось приношення Авидана, сина Гидеонієвого.","В десятий день начальник синів Данових Ахиєзер, син Аммишаддая;","приношення його: одне срібне блюдо, вагою в сто тридцять сиклів, одна срібна чаша в сімдесят сиклів, за сиклем священним, наповнені пшеничним борошном, змішаним з єлеєм, для приношення хлібного,","одна золота кадильниця в десять сиклів, наповнена курінням,","один телець, один баран, один однолітній агнець, у всепалення,","один козел у жертву за гріх,","і в жертву мирну два воли, п’ять баранів, п’ять козлів, п’ять однолітніх агнців; ось приношення Ахиєзера, сина Аммишаддаєвого.","В одинадцятий день начальник синів Асирових Пагиїл, син Охрана;","приношення його: одне срібне блюдо, вагою в сто тридцять сиклів, одна срібна чаша в сімдесят сиклів, за сиклем священним, наповнені пшеничним борошном, змішаним з єлеєм, для приношення хлібного,","одна золота кадильниця в десять сиклів, наповнена курінням,","один телець, один баран, один однолітній агнець, у всепалення,","один козел у жертву за гріх,","і в жертву мирну два воли, п’ять баранів, п’ять козлів, п’ять однолітніх агнців; ось приношення Пагиїла, сина Охранового.","У дванадцятий день начальник синів Неффалимових Ахира, син Енана;","приношення його: одне срібне блюдо, вагою в сто тридцять сиклів, одна срібна чаша в сімдесят сиклів, за сиклем священним, наповнені пшеничним борошном, змішаним з єлеєм, для приношення хлібного,","одна золота кадильниця в десять сиклів, наповнена курінням,","один телець, один баран, один однолітній агнець, у всепалення,","один козел у жертву за гріх,","і в жертву мирну два воли, п’ять баранів, п’ять козлів, п’ять однолітніх агнців; ось приношення Ахири, сина Енанового.","Ось приношення від начальників Ізраїлевих при освяченні жертовника в день помазання його: дванадцять срібних блюд, дванадцять срібних чаш, дванадцять золотих кадильниць;","по сто тридцять сиклів срібла в кожнім блюді і по сімдесят у кожній чаші: отже, всього срібла в цих сосудах дві тисячі чотириста сиклів, за сиклем священним;","золотих кадильниць, наповнених курінням, дванадцять, у кожній кадильниці по десять сиклів, за сиклем священним: усього золота в кадильницях сто двадцять сиклів;","у всепалення всього дванадцять тельців із великої худоби, дванадцять баранів, дванадцять однолітніх агнців і до них хлібне приношення, і в жертву за гріх дванадцять козлів,","і в жертву мирну всього з великої худоби двадцять чотири тельці, шістдесят баранів, шістдесят [однолітніх] козлів, шістдесят однолітніх агнців [без вад]; ось приношення при освяченні жертовника після помазання його.","Коли Мойсей входив у скинію зібрання, щоб говорити з Господом, чув голос, який говорив до нього з кришки, що над ковчегом одкровення між двома херувимами, і він говорив йому."],"x":{"8":"3.4.28","9":"3.3.31|3.4.15|9.6.13","12":"3.1.7|3.2.3","18":"3.1.8|3.2.5","24":"3.1.9|3.2.7","30":"3.1.5|3.2.10","36":"3.1.6|3.2.12","42":"3.1.14|3.2.14","48":"3.1.10|3.2.18","54":"3.1.10|3.2.20","60":"3.1.11|3.2.22|3.10.24","66":"3.1.12|3.2.25","72":"3.1.13|3.2.27","78":"3.1.15|3.2.29"}},{"v":["І сказав Господь Мойсеєві, говорячи:","оголоси Аарону і скажи йому: коли ти будеш запалювати лампади, то на передній стороні світильника повинні горіти сім лампад.","Аарон так і зробив: на передній стороні світильника запалив лампади його, як повелів Господь Мойсеєві.","І ось будова світильника: карбований він із золота, від стебла його і до квітів карбований; за образом, який показав Господь Мойсеєві, він зробив світильник.","І сказав Господь Мойсеєві, говорячи:","візьми левитів із середовища синів Ізраїлевих і очисти їх;","а щоб очистити їх, вчини з ними так: окропи їх очищувальною водою, і нехай вони поголять бритвою все тіло своє і вимиють одяг свій, і будуть чисті;","і нехай візьмуть тельця і хлібне приношення до нього, пшеничного борошна, змішаного з єлеєм, й іншого тельця візьми в жертву за гріх;","і приведи левитів перед скинію зібрання; і збери всю громаду синів Ізраїлевих","і приведи левитів їх перед Господом, і нехай покладуть сини Ізраїлеві руки свої на левитів;","Аарон же нехай звершить над левитами посвяту їх перед Господом від синів Ізраїлевих, щоб відправляли вони служіння Господу;","а левити нехай покладуть руки свої на голову тельців, і принеси одного в жертву за гріх, а іншого у всепалення Господу, для очищення левитів;","і постав левитів перед Аароном і перед синами його, і зверши над ними посвяту їх Господу;","і так відокрем левитів від синів Ізраїлевих, щоб левити були Моїми.","Після цього ввійдуть левити служити скинії зібрання, коли ти очистиш їх і звершиш над ними посвячення їх; тому що вони віддані Мені з синів Ізраїлевих:","замість усіх первістків із синів Ізраїлевих, що розкривають усякі утроби, Я беру їх Собі;","бо Мої всі первістки з синів Ізраїлевих, від людини до худоби: у той день, коли Я уразив усіх первістків у землі Єгипетській, Я освятив їх Собі","і взяв левитів замість усіх первістків у синів Ізраїлевих;","і віддав левитів Аарону і синам його із середовища синів Ізраїлевих, щоб вони відправляли служби за синів Ізраїлевих при скинії зібрання і служили охороною для синів Ізраїлевих, щоб не спостигло синів Ізраїлевих ураження, коли б сини Ізраїлеві приступили до святилища.","І зробили так Мойсей і Аарон і вся громада синів Ізраїлевих з левитами: як повелів Господь Мойсеєві про левитів, так і зробили з ними сини Ізраїлеві.","І очистилися левити й омили одяг свій, і звершив над ними Аарон посвяту їх перед Господом, і очистив їх Аарон, щоб зробити їх чистими;","після цього ввійшли левити відправляти служби свої в скинії зібрання перед Аароном і перед синами його. Як повелів Господь Мойсеєві про левитів, так і зробили вони з ними.","І сказав Господь Мойсеєві, говорячи:","ось закон про левитів: від двадцяти п’яти років і вище повинні вступати вони в службу для робіт при скинії зібрання,","а в п’ятдесят років повинні припиняти виконання робіт і більш не працювати:","тоді нехай допомагають вони братам своїм утримувати варту при скинії зібрання, працювати ж — нехай не працюють; так чини з левитами стосовно служіння їх."],"x":{"2":"1.25.37|1.27.21","4":"1.25.31|10.7.49","6":"3.19.7","7":"2.14.8-9|13.23.6","9":"14.6.18","11":"1.29.24","16":"3.3.12|3.18.6","17":"3.3.13","19":"3.3.9","24":"3.4.3|12.23.3:24"}},{"v":["І сказав Господь Мойсеєві в пустелі Синайській на другий рік після виходу їх із землі Єгипетської, у перший місяць, говорячи:","нехай сини Ізраїлеві звершать Пасху в призначений для неї час:","у чотирнадцятий день цього місяця ввечері звершіть її в призначений для неї час, за всіма постановами і за всіма обрядами її звершіть її.","І сказав Мойсей синам Ізраїлевим, щоб звершили Пасху.","І звершили вони Пасху в перший місяць, у чотирнадцятий день місяця ввечері, у пустелі Синайській: в усьому, як повелів Господь Мойсеєві, так і зробили сини Ізраїлеві.","Були люди, які були нечисті від дотику до мертвих тіл людських, і не могли звершити Пасху в той день; і прийшли вони до Мойсея й Аарона в той день,","і сказали йому ті люди: ми нечисті від дотику до мертвих тіл людських; для чого нас позбавляти того, щоб ми принесли приношення Господу в призначений час серед синів Ізраїлевих?","І сказав їм Мойсей: постійте, я послухаю, що повелить про вас Господь.","І сказав Господь Мойсеєві, говорячи:","скажи синам Ізраїлевим: якщо хто з вас або з нащадків ваших буде нечистий від доторкання до мертвого тіла, або буде в далекій дорозі, то і він повинен звершити Пасху Господню;","у чотирнадцятий день другого місяця ввечері нехай такі звершать її і з опрісноками і гіркими травами нехай їдять її;","і нехай не залишають від неї до ранку і кістки її не розтрощують; нехай звершать її за всіма уставами про Пасху;","а хто чистий і не знаходиться в [далекій] дорозі і не звершить Пасхи, — знищиться душа та з народу свого, тому що він не приніс приношення Господу у свій час: понесе на собі гріх людина та;","якщо буде жити у вас прибулець, то і він повинен звершити Пасху Господню: за уставом про Пасху і за обрядом її він повинен звершити її; один устав нехай буде у вас і для прибульця і для тубільця.","У той день, коли поставлена була скинія, хмара покрила скинію одкровення, і з вечора над скинією ніби вогонь видний був до самого ранку.","Так було і завжди: хмара покривала її [удень] і подоба вогню вночі.","І коли хмара піднімалася від скинії, тоді сини Ізраїлеві вирушали в путь, і на місці, де зупинялася хмара, там зупинялися станом сини Ізраїлеві.","За повелінням Господнім вирушали сини Ізраїлеві в путь, і за повелінням Господнім зупинялися: весь той час, коли хмара стояла над скинією, і вони стояли;","і якщо хмара довгий час була над скинією, то і сини Ізраїлеві додержувалися цієї вказівки Господа і не вирушали;","іноді ж хмара недовгий час була над скинією: вони за вказівкою Господньою зупинялися, і за вказівкою Господньою вирушали у путь;","іноді хмара стояла тільки від вечора до ранку, і зранку піднімалася хмара, тоді і вони вирушали; або день і ніч стояла хмара, і коли піднімалася, і вони тоді вирушали;","або, якщо два дні, або місяць, або кілька днів стояла хмара над скинією, то і сини Ізраїлеві стояли і не вирушали в путь; а коли вона піднімалася, тоді вирушали;","за вказівкою Господньою зупинялися, і за вказівкою Господньою вирушали в путь: додержувалися вказівки Господньої за повелінням Господнім, даним через Мойсея."],"x":{"1":"1.13.4","2":"1.12.3|1.23.15|2.23.5","5":"1.12.6|2.23.5","6":"3.19.11","11":"13.30.2","12":"1.12.46|53.19.36","14":"1.12.49","15":"1.40.34","16":"1.13.21","17":"1.40.36","18":"63.10.1"}},{"v":["І сказав Господь Мойсеєві, говорячи:","зроби собі дві срібні труби, карбованими зроби їх, щоб вони служили тобі для скликання громади і для зняття станів;","коли засурмлять ними, збереться до тебе вся громада до входу в скинію зібрання;","коли однією трубою засурмлять, зберуться до тебе князі й тисячоначальники Ізраїлеві;","коли засурмите тривогу, піднімуться стани, що стають до сходу;","коли в другий раз засурмите тривогу, піднімуться стани, що стають до півдня; [коли засурмите в третій раз тривогу, піднімуться стани, що стають до моря; коли в четвертий раз засурмите тривогу, піднімуться стани, що стають до півночі;] тривогу нехай сурмлять при вирушенні їх у путь;","а коли потрібно зібрати зібрання, сурміть, але не тривогу;","сини Ааронові, священики, повинні сурмити трубами: це буде вам постановою вічною у роди ваші;","і коли підете на війну в землі вашій проти ворога, що нападає на вас, сурміть тривогу трубами, — і будете пом’януті перед Господом, Богом вашим, і врятовані будете від ворогів ваших;","і в день радости вашої, і в свята ваші, і в новомісяччя ваші сурміть трубами при всепаленнях ваших і при мирних жертвах ваших, — і це буде нагадуванням про вас перед Богом вашим. Я Господь, Бог ваш.","У другий рік, у другий місяць, у двадцятий день місяця піднялася хмара від скинії одкровення;","і вирушили сини Ізраїлеві за станами своїми з пустелі Синайської, і зупинилася хмара в пустелі Фаран.","І піднялися вони в перший раз, за велінням Господнім, даним через Мойсея.","Піднято було по-перше прапор стану синів Іудиних за ополченнями їх; над ополченням їх Наассон, син Аминадава;","і над ополченням коліна синів Іссахарових Нафанаїл, син Цуара;","і над ополченням коліна синів Завулонових Елиав, син Хелона.","І знята була скинія, і пішли сини Гирсонові і сини Мерарині, що носять скинію.","І піднято було прапор стану Рувимового за ополченнями їх; і над ополченням його Елицур, син Шедеура;","і над ополченням коліна синів Симеонових Шелумиїл, син Цуришаддая;","і над ополченням коліна синів Гадових Елиасаф, син Регуїла.","Потім пішли сини Каафові, що носять святилище; скинія ж була поставлена до приходу їх.","І піднято було прапор стану синів Єфремових за ополченнями їх; і над ополченнями їх Елишама, син Аммиуда;","і над ополченням коліна синів Манассіїних Гамалиїл, син Педацура;","і над ополченням коліна синів Веніамінових Авидан, син Гидеонія.","Останнім із усіх станів піднято було прапор стану синів Данових з ополченнями їх; і над ополченням Ахиєзер, син Аммишаддая;","і над ополченням коліна синів Асирових Пагиїл, син Охрана;","і над ополченням коліна синів Неффалимових Ахира, син Енана.","Ось порядок ходу синів Ізраїлевих за ополченнями їх. І вирушили вони.","І сказав Мойсей Ховаву, сину Рагуїловому, мадианитянину, родичеві Мойсея: ми вирушаємо в те місце, про яке Господь сказав: вам віддам його; йди з нами, ми зробимо тобі добро, тому що Господь добре прорік про Ізраїль.","Але він сказав йому: не піду; я піду у свою землю і на свою батьківщину.","Мойсей же сказав: не залишай нас, тому що ти знаєш, як розташовуємося ми станом у пустелі, і будеш для нас оком;","якщо підеш з нами, то добро, яке Господь зробить нам, ми зробимо тобі.","І вирушили вони від гори Господньої на три дні путі, і ковчег завіту Господнього йшов перед ними три дні путі, щоб знайти їм місце, де зупинитися.","І хмара Господня осіняла їх вдень, коли вони вирушали зі стану.","Коли піднімався ковчег у путь, Мойсей говорив: встань, Господи, і розвіються вороги Твої, і побіжать від лиця Твого ненависники Твої!","А коли зупинявся ковчег, він говорив: повернись, Господи, до тисяч і десятків тисяч Ізраїля!"],"x":{"3":"3.2.3","6":"3.2.10","8":"1.27.21","9":"3.31.6|13.13.12|24.39.25","10":"3.28.14|11.11.14|13.7.6","12":"3.2.2","14":"3.1.7","15":"3.1.8","16":"3.1.9","17":"3.4.5","18":"3.1.5","19":"3.1.6|3.2.12","20":"3.1.14|3.2.14","22":"3.1.10|3.2.18","23":"3.1.10|3.2.20","24":"3.1.11|3.2.22","25":"3.1.12|3.2.25","26":"3.1.13|3.2.27","27":"3.1.15|3.2.19","29":"1.2.18|1.18.1|1.6.12","33":"4.31.8","35":"25.67.2","36":"13.6.41|25.131.8"}},{"v":["Народ став нарікати вголос на Господа; і Господь почув, і запалав гнів Його, і загорівся у них вогонь Господній, і начав знищувати край стану.","І заволав народ до Мойсея; і помолився Мойсей Господу, і затих вогонь.","І нарекли ім’я місцю цьому: Тавера*, тому що загорівся у них вогонь Господній.","Прибульці між ними стали виявляти примхи; а з ними і сини Ізраїлеві сиділи і плакали й говорили: хто нагодує нас м’ясом?","Ми пам’ятаємо рибу, яку в Єгипті ми їли задарма, огірки і дині, і цибулю, і ріпчасту цибулю і часник;","а нині душа наша знемагає; нічого нема, тільки манна в очах наших.","Манна ж була подібна коріандровому насінню, на вигляд, як бдолах;","народ ходив і збирав її, і молов у жорнах або товк у ступі, і варив у казані, і робив із неї коржі; смак же її подібний був до смаку коржів з єлеєм.","І коли роса сходила на стан уночі, тоді сходила на нього і манна.","Мойсей чув, що народ плаче в сімействах своїх, кожен біля дверей намету свого; і сильно запалав гнів Господній, і прикро було Мойсеєві.","І сказав Мойсей Господу: для чого Ти мучиш раба твого? і чому я не знайшов милости перед очима Твоїми, що Ти поклав на мене тягар усього народу цього?","хіба я носив в утробі весь народ цей, і хіба я народив його, що Ти говориш мені: неси його на руках твоїх, як нянька носить дитину, в землю, що Ти з клятвою обіцяв батькам його?","звідки мені взяти м’яса, щоб дати всьому народу цьому? бо вони плачуть переді мною і говорять: дай нам їсти м’яса.","Я один не можу нести весь народ цей, тому що він важкий для мене;","коли Ти так чиниш зі мною, то краще умертви мене, якщо я знайшов милість в очах Твоїх, щоб мені не бачити нещастя мого.","І сказав Господь Мойсею: збери Мені сімдесят мужів зі старійшин Ізраїлевих, яких ти знаєш, що вони старійшини і наглядачі його, і візьми їх до скинії зібрання, щоб вони стали там з тобою;","Я зійду, і буду говорити там з тобою, і візьму від Духа, Який на тобі, і покладу на них, щоб вони несли з тобою тягар народу, а не один ти носив.","Народу ж скажи: очистіться до завтрашнього дня, і будете їсти м’ясо; оскільки ви плакали голосно до Господа і говорили: хто нагодує нас м’ясом? добре нам було в Єгипті, — то і дасть вам Господь м’ясо, і будете їсти [м’ясо]:","не один день будете їсти, не два дні, не п’ять днів, не десять днів і не двадцять днів,","але цілий місяць [будете їсти], поки не піде воно з ніздрів ваших і не зробиться для вас огидним, за те, що ви знехтували Господа, Який серед вас, і плакали перед Ним, говорячи: для чого було нам виходити з Єгипту?","І сказав Мойсей: шістсот тисяч піших у народі цьому, серед якого я знаходжуся; а Ти говориш: Я дам їм м’ясо, і будуть їсти цілий місяць!","чи заколоти всіх овець і волів, щоб їм вистачило? або вся риба морська збереться, щоб задовольнити їх?","І сказав Господь Мойсею: хіба рука Господня коротка? нині ти побачиш, чи збудеться слово Моє до тебе, чи ні?","Мойсей вийшов і сказав народу слова Господні, і зібрав сімдесят мужів зі старійшин народу і поставив їх біля скинії.","І зійшов Господь у хмарі, і говорив з ним, і взяв від Духа, Який на ньому, і дав сімдесятьом мужам старійшинам. І коли спочив на них Дух, вони стали пророкувати, але потім перестали.","Двоє з мужів залишилися в стані, одному ім’я Елдад, а другому ім’я Модад; але і на них спочив Дух [вони були з числа записаних, тільки не входили до скинії], і вони пророкували в стані.","І прибіг отрок, і доніс Мойсеєві, і сказав: Елдад і Модад пророкують у стані.","У відповідь на це Ісус, син Навина, служитель Мойсея, один із обраних його, сказав: господарю мій Мойсею! заборони їм.","Але Мойсей сказав йому: чи не ревнуєш ти за мене? о, якби усі в народі Господньому були пророками, коли б Господь послав Духа Свого на них!","І повернувся Мойсей у стан, він і старійшини Ізраїлеві.","І піднявся вітер від Господа, і приніс від моря перепелів, і накидав їх біля стану, на день шляху по одну сторону і на день шляху по другу сторону біля стану, майже на два лікті від землі.","І встав народ, і весь той день, і всю ніч, і весь наступний день збирали перепелів; і хто мало збирав, той зібрав десять хомерів; і розклали їх для себе навколо стану.","М’ясо ще було в зубах їхніх і не було ще з’їдене, як гнів Господній запалав на народ, і вразив Господь народ дуже великою пошестю.","І нарекли ім’я місцю цьому: Киброт-Гаттаава*, тому що там поховали примхливий народ.","Від Киброт-Гаттаави рушив народ в Асироф, і зупинився в Асирофі."],"x":{"1":"3.21.4|2.10.2|25.77.21","2":"40.7.5","3":"4.9.22","4":"1.12.38|63.10.6","6":"3.21.5","7":"1.16.14|25.77.24|29.16.20|53.6.31|63.10.3","9":"1.16.14","12":"4.1.35","14":"4.1.19","15":"1.32.32","16":"1.18.21|3.16.25","17":"63.12.4|1.18.26","18":"1.19.10","20":"3.21.5","21":"3.20.10|50.14.15|53.6.5","22":"50.15.33|51.8.4","23":"31.50.2|31.59.1","25":"3.12.5|8.10.6|39.2.28","28":"3.13.9|69.5.19","31":"1.16.13|25.77.27|25.104.40|29.19.11","33":"25.77.30-31","35":"3.13.1|3.33.16"},"n":{"3":["Горіння."],"34":["Гроби примхи."]}},{"v":["І дорікали Маріам і Аарон Мойсею за дружину ефіоплянку, яку він узяв, — тому що він узяв за себе ефіоплянку, —","і сказали: чи одному Мойсеєві говорив Господь? чи не говорив Він і нам? І почув це Господь.","Мойсей же був чоловік найлагідніший з усіх людей на землі.","І сказав Господь раптово Мойсею й Аарону і Маріамі: вийдіть ви троє до скинії зібрання. І вийшли всі троє.","І зійшов Господь у хмарному стовпі, і став біля входу в скинію, і покликав Аарона і Маріам, і вийшли вони обоє.","І сказав: слухайте слова Мої: якщо буває у вас пророк Господній, то Я відкриваюся йому у видінні, уві сні говорю з ним;","але не так з рабом Моїм Мойсеєм, — він вірний у всьому домі Моїм:","вустами до вуст говорю Я з ним, і явно, а не в гаданнях, і образ Господа він бачить; як же ви не убоялися дорікати рабу Моєму, Мойсеєві?","І запалав гнів Господа на них, і Він відійшов.","І хмара відійшла від скинії, і ось, Маріам вкрилася проказою, як снігом. Аарон глянув на Маріам, і ось, вона у проказі.","І сказав Аарон Мойсеєві: господарю мій! не постав нам за гріх, що ми вчинили нерозумно і згрішили;","не попусти, щоб вона була, як мертвонароджена дитина, в якої, коли вона виходить із утроби матері своєї, зотліла уже половина тіла.","І звернувся Мойсей до Господа, говорячи: Боже, зціли її!","І сказав Господь Мойсеєві: якби батько її плюнув їй у лице, то чи не повинна була б вона соромитися сім днів? отже, нехай буде вона у проказі сім днів поза станом, а після знову повернеться.","І пробула Маріам у проказі поза станом сім днів, і народ не вирушав у путь, доки не повернулася Маріам."],"x":{"1":"3.16.2|1.2.21","3":"1.11.8|50.11.29","5":"1.16.10|3.11.17|3.14.10","6":"8.3.7","7":"75.3.5","8":"1.33.11|4.34.10|63.13.12","9":"3.11.3","10":"4.24.9","12":"11.5.10","14":"2.13.46|2.14.8"}},{"v":["Після цього народ рушив із Асирофа, і зупинився в пустелі Фаран.","І сказав Господь Мойсеєві, говорячи:","пошли від себе людей, щоб вони видивилися землю Ханаанську, яку Я даю синам Ізраїлевим; по одній людині від коліна батьків їх пошліть, головних з них.","І послав їх Мойсей з пустелі Фаран, за велінням Господнім, і усі вони мужі головні серед синів Ізраїлевих.","Ось імена їхні: з коліна Рувимового Саммуа, син Закхурів,","з коліна Симеонового Сафат, син Хориїв,","з коліна Іудиного Халев, син Ієфонніїн,","з коліна Іссахарового Ігал, син Йосифів,","з коліна Єфремового Осія, син Навина,","з коліна Веніамінового Фалтій, син Рафуїв,","з коліна Завулонового Гаддиїл, син Содиїв,","з коліна Йосифового від Манассії Гаддій, син Сусіїв,","з коліна Данового Аммиїл, син Гемалліїв,","з коліна Асирового Сефур, син Михаїлів,","з коліна Неффалимового Нахбій, син Вофсіїв,","з коліна Гадового Геуїл, син Махіїв.","Ось імена мужів, яких посилав Мойсей оглянути землю. І назвав Мойсей Осію, сина Навина, Ісусом.","І послав їх Мойсей [з пустелі Фаран] оглянути землю Ханаанську і сказав їм: підіть у цю південну країну, і зійдіть на гору,","і огляньте землю, яка вона, і народ, який живе на ній, сильний він чи слабкий, нечисленний він чи численний?","і яка земля, на якій він живе, добра вона чи погана? і які міста, в яких він живе, у наметах він живе чи в укріпленнях?","і яка земля, жирна вона чи пісна? чи є на ній дерева? будьте сміливими, і візьміть від плодів землі. Було ж це в час дозрівання винограду.","Вони пішли і оглянули землю від пустелі Син навіть до Рехова, поблизу Емафа;","і пішли в південну країну, і дійшли до Хеврона, де жили Ахиман, Сесай і Фалмай, діти Енакові: Хеврон же був побудований на сім років раніше Цоана, [міста] єгипетського;","і прийшли до долини Есхол, [і оглянули її,] і зрізали там виноградну гілку з одним гроном ягід, і понесли її на жердині двоє; взяли також гранатових яблук і смокв;","місце це назвали долиною Есхол*, через виноградне гроно, яке зрізали там сини Ізраїлеві.","І оглянувши землю, повернулися вони через сорок днів.","І пішли і прийшли до Мойсея й Аарона і до всієї громади синів Ізраїлевих у пустелю Фаран, у Кадес, і принесли їм і всій громаді відповідь, і показали їм плоди землі;","і розповідали їм і говорили: ми ходили в землю, в яку ти посилав нас; у ній справді тече молоко і мед, і ось плоди її;","але народ, що живе на землі тій, сильний, і міста укріплені, дуже великі, і синів Енакових ми бачили там;","Амалик живе на південній частині землі, хеттеї, [евеї,] ієвусеї й аморреї живуть на горі, хананеї ж живуть біля моря і на березі Йордану.","Але Халев заспокоював народ перед Мойсеєм, говорячи: підемо і заволодіємо нею, тому що ми можемо подолати її.","А ті, які ходили з ним, говорили: не можемо ми йти проти народу цього, тому що він сильніший за нас.","І розпускали недобрі чутки про землю, яку вони оглядали, між синами Ізраїлевими, говорячи: земля, яку проходили ми для огляду, є земля, що поїдає тих, що живуть на ній, і весь народ, який ми бачили на ній, люди високі на зріст;","там бачили ми і велетнів, синів Енакових, від велетенського роду; і ми були в очах наших перед ними, як сарана, такими ж були ми й в очах їхніх."],"x":{"1":"3.11.35|3.33.17","3":"4.1.22|4.9.23","4":"4.1.22","7":"5.14.7","18":"3.32.8","22":"9.8.9","23":"4.1.28|4.2.10","24":"3.32.9|4.1.24","27":"0.14.7|4.1.19","28":"1.3.8|4.1.25","30":"5.11.3","31":"3.14.6:24|5.14.8","34":"0.6.4|4.9.2"},"n":{"25":["Виноградне гроно."]}},{"v":["І підняла вся громада крик, і плакав народ в [усю] ту ніч;","і нарікали на Мойсея та Аарона всі сини Ізраїлеві, і вся громада сказала їм: о, якби ми померли в землі Єгипетській, або померли б у пустелі цій!","і для чого Господь веде нас у землю цю, щоб ми впали від меча? дружини наші і діти наші дістануться у здобич ворогам; чи не краще нам повернутися в Єгипет?","І сказали одне одному: поставимо собі начальника і повернемося в Єгипет.","І впали Мойсей й Аарон на обличчя свої перед всім зібранням громади синів Ізраїлевих.","І Ісус, син Навина, і Халев, син Ієфонніїн, з тих, які оглядали землю, роздерли одяг свій","і сказали всій громаді синів Ізраїлевих: земля, яку ми проходили для огляду, дуже, дуже добра;","якщо Господь милостивий до нас, то введе нас у землю цю і дасть нам її — цю землю, в якій тече молоко і мед;","тільки проти Господа не повставайте і не бійтеся народу землі цієї; бо він дістанеться нам на поживу: захисту в них не стало, а з нами Господь; не бійтесь їх.","І сказала вся громада: побити їх камінням! Але слава Господня явилася [у хмарі] у скинії зібрання всім синам Ізраїлевим.","І сказав Господь Мойсеєві: доки буде дратувати Мене народ цей? і доки буде він не вірити Мені при всіх знаменнях, які Я робив серед нього?","вражу його пошестю і знищу його і породжу від тебе [і від дому батька твого] народ численніший і сильніший за нього.","Але Мойсей сказав Господу: почують єгиптяни, з середовища яких Ти вивів силою Твоєю народ цей,","і скажуть жителям землі цієї, які чули, що Ти, Господь, знаходишся серед народу цього, і що Ти, Господь, даєш їм бачити Себе лицем до лиця, і хмара Твоя стоїть над ними, і Ти йдеш перед ними вдень у стовпі хмарному, а вночі в стовпі вогненному;","і якщо Ти знищиш народ цей, як одну людину, то народи, які чули славу Твою, скажуть:","Господь не міг ввести народ цей у землю, яку Він із клятвою обіцяв йому, а тому й знищив його в пустелі.","Отже, нехай звеличиться сила Господня, як Ти сказав, говорячи:","Господь довготерпеливий і многомилостивий [і істинний], Який прощає беззаконня і провини [і гріхи], і Який не залишає без покарання, але карає беззаконня батьків на дітях до третього і четвертого роду.","Прости гріх народу цьому з великої милости Твоєї, як Ти прощав народ цей від Єгипту до цього.","І сказав Господь [Мойсеєві]: прощаю за словом твоїм;","але живий Я, [і завжди живе ім’я Моє,] і славою Господньою повна вся земля:","усі, які бачили славу Мою і знамення Мої, зроблені Мною в Єгипті й у пустелі, і спокушали Мене вже десять разів і не слухали голосу Мого,","не побачать землі, яку Я з клятвою обіцяв батькам їх; [тільки дітям їх, що тут зі Мною, що не знають, що добро, що зло, усім малолітнім, хто нічого не розуміє, їм дам землю, а] усі, що дратували Мене, не побачать її;","але раба Мого, Халева, за те, що в ньому був інший дух, і він повністю підкорювався Мені, введу в землю, в яку він ходив, і сім’я його успадкує її;","амаликитяни і хананеї живуть у долині; завтра поверніться і йдіть у пустелю до Червоного моря.","І сказав Господь Мойсеєві й Аарону, говорячи:","доки злій громаді цій нарікати на Мене? ремство синів Ізраїлевих, яким вони нарікають на Мене, Я чую.","Скажи їм: живу Я, говорить Господь: як говорили ви вголос Мені, так і зроблю вам;","у пустелі цій упадуть тіла ваші, й усі ви пораховані, скільки вас за кількістю, від двадцяти років і вище, які нарікали на Мене,","не ввійдете в землю, на якій Я, піднявши руку Мою, клявся оселити вас, крім Халева, сина Ієфонніїного, та Ісуса, сина Навина;","дітей ваших, про яких ви говорили, що вони дістануться у здобич ворогам, Я введу туди, і вони пізнають землю, яку ви знехтували,","а ваші трупи упадуть у пустелі цій;","а сини ваші будуть кочувати в пустелі сорок років, і будуть нести покарання за блудодійство ваше, доки не загинуть усі тіла ваші в пустелі;","за числом сорока днів, в які ви оглядали землю, ви понесете покарання за гріхи ваші сорок років, рік за день, щоб ви пізнали, що означає бути залишеним Мною.","Я, Господь, говорю, і так і зроблю з усією цією злою громадою, що повстала проти Мене: в пустелі цій усі вони загинуть і перемруть.","І ті, яких посилав Мойсей для огляду землі, і які, повернувшись, підбурили проти нього всю цю громаду, розпускаючи злі чутки про землю,","ці, що розпустили злі чутки про землю, померли, будучи ураженими перед Господом;","тільки Ісус, син Навина, і Халев, син Ієфонніїн, залишилися живими з тих мужів, які ходили оглядати землю.","І сказав Мойсей слова ці перед усіма синами Ізраїлевими, і народ дуже засмутився.","І, вставши рано-вранці, пішли на вершину гори, говорячи: ось, ми підемо на те місце, про яке сказав Господь, бо ми згрішили.","Мойсей сказав: для чого ви переступаєте повеління Господні? це буде безуспішно;","не ходіть, бо немає серед вас Господа, щоб не уразили вас вороги ваші;","бо амаликитяни і хананеї там перед вами, і ви впадете від меча, тому що ви відступили від Господа, і не буде з вами Господа.","Але вони наважилися піднятися на вершину гори; ковчег же завіту Господнього і Мойсей не залишали стану.","І зійшли амаликитяни і хананеї, що живуть на горі тій, і розбили їх, і гнали їх до Хорми, [і повернулися в стан.]"],"x":{"1":"3.21.5|4.1.27|25.105.25","2":"3.16.3","3":"16.1.18","5":"3.16.4","6":"30.46.9|21.2.55-56","8":"1.3.8|3.13.28","9":"4.20.3|4.32.42","10":"1.17.4","12":"1.32.10","13":"1.32.12","14":"1.13.21","15":"1.32.12","16":"4.9.28","18":"25.102.8|1.20.5|4.5.9|32.32.18","19":"1.32.12","21":"4.1.35","22":"17.4.12|27.7.20","23":"4.1.35|25.94.11|75.3.11","24":"5.14.6|6.1.20|21.2.56","27":"25.105.25","29":"3.26.65|3.32.11|4.1.35|25.105.26","30":"3.26.65|4.1.36|5.14.6","33":"25.94.10","34":"25.94.10","37":"61.1.5|63.10.10|75.3.11","38":"30.46.10","40":"4.1.41","44":"4.1.43","45":"6.1.17"}},{"v":["І сказав Господь Мойсеєві, говорячи:","оголоси синам Ізраїлевим і скажи їм: коли ви ввійдете в землю вашого поселення, яку Я даю вам,","і будете приносити жертву Господу, всепалення, або жертву, для якої заколюються воли і вівці, на виконання обітниці, або з ревности, або у свята ваші, щоб зробити приємні пахощі Господу, —","тоді той, хто приносить жертву свою Господу, повинен принести у приношення від хліба десяту частину [ефи] пшеничного борошна, змішаного с четвертою частиною гина єлею;","і вина для узливання принось четверту частину гина при всепаленні, або при жертві, що заколюється, на кожного агнця [у приємні пахощі Господу].","А приносячи барана, принось у приношення хлібне дві десятих частини ефи пшеничного борошна, змішаного з третьою частиною гина єлею;","і вина для узливання принось третю частину гина в приємні пахощі Господу.","Якщо молодого вола приносиш у всепалення, або жертву, що заколюється, на виконання обітниці, або в мирну жертву Господу,","то разом з волом слід принести приношення хлібного три десятих частини ефи пшеничного борошна, змішаного з половиною гина єлею;","і вина для узливання принось півгина в жертву, у приємні пахощі Господу.","Так роби при кожному приношенні вола і барана й агнця із овець, або кіз;","за числом жертв, які ви приносите, так робіть при кожній, за числом їх.","Всякий тубілець так повинен робити це, приносячи жертву у приємні пахощі Господу;","і якщо буде між вами жити прибулець, або хто б не був серед вас у роди ваші, і принесе жертву в приємні пахощі Господу, то і він повинен робити так, як ви робите;","для вас, громада [Господня], і для прибульця, що живе [у вас], устав один, устав вічний у роди ваші: що ви, те і прибулець нехай буде перед Господом;","закон один і одні права нехай будуть для вас і для прибульця, що живе у вас.","І сказав Господь Мойсеєві, говорячи:","оголоси синам Ізраїлевим і скажи їм: коли ви увійдете в землю, в яку Я веду вас,","і будете їсти хліб тієї землі, то приносьте приношення Господу;","від початків тіста вашого корж приносьте у приношення; приносьте його так, як приношення з току;","від початків тіста вашого віддавайте в приношення Господу в роди ваші.","Якщо ж переступите з невідання і не виконаєте всіх цих заповідей, які проголосив Господь Мойсеєві,","всього, що заповів вам Господь [Бог] через Мойсея, від того дня, в який Господь заповів вам, і надалі в роди ваші, —","то, коли з недогляду громади зроблена помилка, нехай уся громада принесе одного молодого вола [без вад] у всепалення, у приємні пахощі Господу, з хлібним приношенням й узливанням його, за уставом, і одного козла в жертву за гріх;","і очистить священик усю громаду синів Ізраїлевих, і буде прощено їм, тому що це була помилка, і вони принесли приношення своє в жертву Господу, і жертву за гріх свій перед Господом, за свою помилку;","і буде прощено всій громаді синів Ізраїлевих і прибульцеві, який живе між ними, тому що весь народ зробив це помилково.","Якщо ж один хто згрішить з невідання, то нехай принесе козу однолітню в жертву за гріх;","і очистить священик душу, що зробила помилково гріх перед Господом, і очищена буде, і прощено буде їй;","один закон нехай буде для вас, як для природного жителя з синів Ізраїлевих, так і для прибульця, який живе у вас, якщо хто зробить що помилково.","Якщо ж хто з тубільців, або з прибульців, зробить що зухвалою рукою, то він хулить Господа: знищиться душа та з народу свого,","бо слово Господнє він знехтував і заповідь Його порушив; знищиться душа та; гріх її на ній.","Коли сини Ізраїлеві були в пустелі, знайшли чоловіка, який збирав дрова в день суботи;","і привели його ті, які знайшли його, що збирав дрова [в день суботи] до Мойсея та Аарона і до всієї громади [синів Ізраїлевих];","і посадили його під варту, тому що не було ще визначено, що слід з ним зробити.","І сказав Господь Мойсеєві: повинен умерти чоловік цей; нехай поб’є його камінням уся громада поза станом.","І вивела його вся громада геть зі стану, і побили його камінням, і він помер, як повелів Господь Мойсею.","І сказав Господь Мойсеєві, говорячи:","оголоси синам Ізраїлевим і скажи їм, щоб вони робили собі китиці на краях одягу свого в роди їх, і в китиці, що на краях, вставляли нитки з блакитної вовни;","і будуть вони в китицях у вас для того, щоб ви, дивлячись на них, згадували всі заповіді Господні, і виконували їх, і не ходили услід серця вашого й очей ваших, які тягнуть вас до блудодійства,","щоб ви пам’ятали і виконували всі заповіді Мої і були святі перед Богом вашим.","Я Господь, Бог ваш, Який вивів вас із землі Єгипетської, щоб бути вашим Богом: Я Господь, Бог ваш."],"x":{"3":"2.7.16|1.29.18","4":"2.2.5|1.16.36","13":"2.1.17|2.3.5:16","15":"1.12.49|2.24.22|3.9.14","16":"4.1.16","19":"1.23.15-16","20":"17.10.37|2.23.10-11","22":"2.4.13","24":"2.4.13","27":"2.4.27","29":"1.12.49|2.24.22","32":"1.20.8","34":"2.24.12","36":"5.7.25","38":"4.22.12|50.23.5","40":"50.15.3","41":"1.20.2|2.11.45|0.17.7"}},{"v":["Корей, син Іцгара, син Каафів, син Левія, і Дафан і Авирон, сини Елиава, й Авнан, син Фалефа, сини Рувимові,","повстали проти Мойсея, і з ними із синів Ізраїлевих двісті п’ятдесят мужів, начальники громади, яких закликали на зібрання, люди вельможні.","І зібралися проти Мойсея й Аарона і сказали їм: досить вам; уся громада, усі святі, і серед них Господь! чому ж ви ставите себе вище народу Господнього?","Мойсей, почувши це, упав на лице своє","і сказав Корею і всім спільникам його, говорячи: завтра покаже Господь, хто Його, і хто святий, щоб наблизити його до Себе; і кого Він обере, того і наблизить до Себе;","ось що зробіть: Корей і всі спільники його візьміть собі кадильниці","і завтра покладіть у них вогонь і всипите в них куріння перед Господом; і кого обере Господь, той і буде святий. Годі вам, сини Левіїни!","І сказав Мойсей Корею: послухайте, сини Левія!","невже мало вам того, що Бог Ізраїлів відокремив вас від суспільства Ізраїльського і наблизив вас до Себе, щоб ви виконували служби при скинії Господній і стояли перед громадою [Господньою], щоб служити їй?","Він наблизив тебе і з тобою всіх братів твоїх, синів Левія, і ви домагаєтеся ще й священства.","Отже, ти й уся твоя громада зібралися проти Господа. Що Аарон, що ви нарікаєте на нього?","І послав Мойсей покликати Дафана й Авирона, синів Елиава. Але вони сказали: не підемо!","хіба мало того, що ти вивів нас із землі, в якій тече молоко і мед, щоб погубити нас у пустелі? і ти ще хочеш панувати над нами!","чи привів ти нас у землю, де тече молоко і мед, і чи дав нам у володіння поля і виноградники? очі людей цих ти хочеш засліпити? не підемо!","Мойсей дуже засмутився і сказав Господу: не звертай погляду Твого на приношення їхні; я не взяв у жодного з них осла і не зробив зла жодному з них.","І сказав Мойсей Корею: завтра ти й уся громада твоя будьте перед лицем Господа, ти, вони й Аарон;","і візьміть кожен свою кадильницю, і покладіть у них куріння, і принесіть перед лице Господнє кожен свою кадильницю, двісті п’ятдесят кадильниць; ти й Аарон, кожен свою кадильницю.","І взяв кожен свою кадильницю, і поклали в них вогню, і всипали в них куріння, і стали при вході у скинію зібрання; також і Мойсей і Аарон.","І зібрав проти них Корей усю громаду до входу в скинію зібрання. І з’явилася слава Господня всій громаді.","І сказав Господь Мойсеєві й Аарону, говорячи:","відокремтеся від громади цієї, і Я знищу їх умить.","Вони ж упали на лиця свої і сказали: Боже, Боже духів усякої плоті! одна людина згрішила, і Ти гніваєшся на всю громаду?","і сказав Господь Мойсеєві, говорячи:","скажи громаді: відступіть з усіх боків від житла Корея, Дафана й Авирона.","І встав Мойсей, і пішов до Дафана й Авирона, і за ним пішли старійшини Ізраїлеві.","І сказав громаді: відійдіть від наметів нечестивих людей цих, і не доторкайтеся ні до чого, що належить їм, щоб не загинути вам [разом] у всіх гріхах їхніх.","І відійшли вони з усіх боків від житла Корея, Дафана й Авирона; а Дафан і Авирон вийшли і стояли біля дверей наметів своїх з дружинами своїми і синами своїми і з малими дітьми своїми.","І сказав Мойсей: з цього довідаєтеся, що Господь послав мене робити всі діла ці, не за своєю волею [я роблю це]:","якщо вони помруть, як помирають усі люди, і спостигне таке покарання, яке спостигає всіх людей, то не Господь послав мене;","а якщо Господь сотворить надзвичайне, і земля розверзне вуста свої і поглине їх [і доми їх і намети їх] і усе, що в них, і вони живими зійдуть у пекло, то знайте, що люди ці знехтували Господа.","Лиш тільки він сказав слова ці, розсілася земля під ними;","і розверзла земля вуста свої, і поглинула їх і доми їх, і всіх людей Кореєвих і все майно;","і зійшли вони з усім, що належало їм, живими в пекло, і покрила їх земля, і загинули вони із середовища громади.","І всі ізраїльтяни, які були навколо них, побігли волаючи, щоб, говорили вони, і нас не поглинула земля.","І вийшов вогонь від Господа і пожер тих двісті п’ятдесят мужів, що принесли куріння.","І сказав Господь Мойсеєві, говорячи:","скажи Єлеазару, сину Аарона, священикові, нехай він збере [мідні] кадильниці спалених і вогонь викине геть; бо освятилися","кадильниці грішників цих смертю їх, і нехай розіб’ють їх на листи для покриття жертовника, бо вони принесли їх перед лице Господа, і вони зробилися освяченими; і будуть вони знаменням для синів Ізраїлевих.","І взяв Єлеазар священик мідні кадильниці, які принесли спалені, і розбили їх на листи для покриття жертовника,","у пам’ять синам Ізраїлевим, щоб ніхто сторонній, який не від сімені Аарона, не приступав приносити кадіння перед лице Господнє, і не було з ним того, що з Кореєм і спільниками його, як говорив йому Господь через Мойсея.","На другий день уся громада синів Ізраїлевих нарікала на Мойсея й Аарона і говорила: ви умертвили народ Господній.","І коли зібралася громада проти Мойсея й Аарона, вони обернулися до скинії зібрання, і ось, хмара покрила її, і з’явилася слава Господня.","І прийшов Мойсей і Аарон до скинії зібрання.","І сказав Господь Мойсеєві [й Аарону], говорячи:","відстороніться від громади цієї, і Я знищу їх умить. Але вони впали на лиця свої.","І сказав Мойсей Аарону: візьми кадильницю і поклади в неї вогню з жертовника і всип куріння, і неси швидше до громади і заступи їх, тому що вийшов гнів від Господа, [і] почалось ураження.","І взяв Аарон, як сказав Мойсей, і побіг у середовище громади, і ось, уже почалось ураження в народі. І він поклав куріння і заступив народ;","став він між мертвими й живими, й ураження припинилося.","І померло від ураження чотирнадцять тисяч сімсот чоловік, крім померлих у справі Кореєвій.","І повернувся Аарон до Мойсея, до входу в скинію зібрання, після того, як ураження припинилося."],"x":{"1":"3.26.9|3.27.3|30.45.22|61.1.11|1.6.21","2":"3.12.1|1.18.22","3":"3.14.2|3.20.2","4":"3.14.5","9":"3.3.6","11":"1.16.7","14":"1.3.8|1.13.5|1.33.3","15":"0.4.4-5","19":"1.16.10|2.9.23","22":"25.30.6|25.145.4|52.8.55|9.24.17","24":"3.12.15","30":"3.27.3|4.11.6|25.105.17","31":"3.26.10","35":"2.10.2","41":"3.14.2|3.20.3","42":"1.16.10|3.12.5","46":"29.18.21"}},{"v":["І сказав Господь Мойсеєві, говорячи:","скажи синам Ізраїлевим і візьми в них по жезлу від коліна, від усіх начальників їхніх за колінами, дванадцять жезлів, і кожного ім’я напиши на жезлі його;","ім’я Аарона напиши на жезлі Левія, бо один жезл від начальника коліна їхнього [повинні вони дати];","і поклади їх у скинії зібрання, перед ковчегом одкровення, де явлюся Я вам;","і кого Я оберу, того жезл розцвіте; і так Я заспокою ремство синів Ізраїлевих, яким вони нарікають на вас.","І сказав Мойсей синам Ізраїлевим, і дали йому всі начальники їхні, від кожного начальника по жезлу, за колінами їхніми дванадцять жезлів, і жезл Ааронів був серед жезлів їхніх.","І поклав Мойсей жезли перед лицем Господа в скинії одкровення.","На другий день увійшов Мойсей [і Аарон] у скинію одкровення, і ось, жезл Ааронів, від дому Левіїного, розцвів, пустив бруньки, дав цвіт і приніс мигдалини.","І виніс Мойсей усі жезли від лиця Господнього до всіх синів Ізраїлевих. І побачили вони це і взяли кожен свій жезл.","І сказав Господь Мойсеєві: поклади знову жезл Ааронів перед ковчегом одкровення для збереження, на знамення для непокірливих, щоб припинилося ремство їх на Мене, і вони не вмирали.","Мойсей зробив це; як повелів йому Господь, так він і зробив.","І сказали сини Ізраїлеві Мойсеєві: ось, ми вмираємо, гинемо, усі гинемо!","усякий, хто наближається до скинії Господньої, помирає: чи не доведеться всім нам померти?"],"x":{"4":"1.25.22","8":"75.9.4|31.11.1","10":"75.9.10","13":"31.64.12"}},{"v":["І сказав Господь Аарону: ти і сини твої і дім батька твого з тобою понесете на собі гріх за недбалість у святилищі; і ти і сини твої з тобою понесете на собі гріх за несправність у священстві вашому.","Також і братів твоїх, коліно Левіїне, плем’я батька твого, візьми собі: нехай вони будуть при тобі і служать тобі, а ти і сини твої з тобою будете при скинії одкровення;","нехай вони відправляють службу тобі і службу в усій скинії; тільки щоб не приступали до речей святилища і до жертовника, щоб не померти і їм і вам.","Нехай вони будуть при тобі і відправляють службу в скинії зібрання, усі роботи по скинії; а сторонній не повинен наближатися до вас.","Так відправляйте службу у святилищі і при жертовнику, щоб не було надалі гніву на синів Ізраїлевих;","бо братів ваших, левитів, Я взяв від синів Ізраїлевих і дав їх вам, у дар Господу, для відправляння служби при скинії зібрання;","і ти і сини твої з тобою пильнуйте священство ваше в усьому, що належить жертовнику і що всередині за завісою, і служіть; вам даю Я в дар службу священства, а сторонній, який приступить, відданий буде на смерть.","І сказав Господь Аарону: ось, Я доручаю тобі спостерігати за приношеннями Мені; від усього, що посвячується синами Ізраїлевими, Я дав тобі і синам твоїм, заради священства вашого, уставом вічним;","ось, що належить тобі зі святинь великих, від того, що спалюється: усяке приношення їхнє хлібне, і всяка жертва їхня за гріх, і всяка жертва їхня за провину, що вони принесуть Мені; це велика святиня тобі і синам твоїм.","На найсвятішому місці їжте це; усі чоловічої статі можуть їсти, [ти і сини твої]; це нехай буде святинею для тебе.","І ось, що тобі з приношень дарів їхніх: усі приношення синів Ізраїлевих Я дав тобі і синам твоїм і дочкам твоїм з тобою, уставом вічним; усякий чистий у домі твоєму може їсти це.","Усе краще з єлею і все краще з винограду і хліба, початки їх, що вони дають Господу, Я віддав тобі;","усі перші плоди землі їх, що вони принесуть Господу, нехай будуть твоїми; усякий чистий у домі твоєму може їсти це.","Усе закляте в землі Ізраїлевій нехай буде твоїм.","Усе, що розкриває утробу в усякій плоті, що приносять Господу, з людей і з худоби, нехай буде твоїм; тільки первісток з людей повинен бути викупленим, і первородне з худоби нечистої повинне бути викупленим;","а викуп за них: починаючи від одного місяця, за оцінкою твоєю, бери викуп п’ять сиклів срібла, за сиклем священним, який у двадцять гер;","але за первородне з волів, і за первородне з овець, і за первородне з кіз, не бери викупу: вони святиня; кров’ю їх окроплюй жертовник, і жир їх спалюй у жертву, у приємні пахощі Господу;","м’ясо ж їх тобі належить, так само як груди приношення і праве плече тобі належать.","Усі принесені святині, які приносять сини Ізраїлеві Господу, віддаю тобі і синам твоїм і дочкам твоїм з тобою, уставом вічним; це завіт соли вічний перед Господом, даний тобі і нащадкам твоїм з тобою.","І сказав Господь Аарону: в землі їхній не будеш мати наділу і частки не буде тобі між ними; Я частка твоя і наділ твій серед синів Ізраїлевих;","а синам Левія, ось, Я дав у наділ десятину з усього, що в Ізраїля, за службу їх, за те, що вони відправляють служби в скинії зібрання;","і сини Ізраїлеві не повинні надалі приступати до скинії зібрання, щоб не понести гріха і не померти:","нехай левити відправляють служби в скинії зібрання і несуть на собі гріх їхній. Це устав вічний у роди ваші; серед же синів Ізраїлевих вони не одержать наділу;","тому що десятину синів Ізраїлевих, яку вони приносять у приношення Господу, Я віддаю левитам у наділ, тому і сказав Я їм: між синами Ізраїлевими вони не одержать наділу.","І сказав Господь Мойсеєві, говорячи:","оголоси левитам і скажи їм: коли ви будете брати від синів Ізраїлевих десятину, яку Я дав вам від них у наділ, то підносьте з неї приношення Господу, десятину із десятини, —","і буде враховане вам це приношення ваше, як хліб з току і як взяте від точила;","так і ви будете підносити приношення Господу з усіх десятин ваших, які будете брати від синів Ізраїлевих, і будете давати з них приношення Господнє Ааронові священику;","з усього, що дарується вам, приносьте приношення Господу, з усього кращого, що освячується.","І скажи їм: коли ви принесете із цього краще, то це враховане буде левитам, як одержане з току і одержане від точила;","ви можете їсти це на всякому місці, ви і [сини ваші і] сімейства ваші, тому що це вам плата за працю вашу в скинії зібрання;","і не понесете за це гріха, коли принесете краще з цього; і посвяченого синами Ізраїлевими не оскверните, і не помрете."],"x":{"6":"5.13.14","7":"3.3.10|3.16.40","8":"2.6.16:29|3.31.41","9":"2.2.3|30.7.33-34","10":"2.6.16|2.7.6","11":"30.7.33","12":"17.10.37","14":"2.27.28","15":"1.34.19","16":"1.30.13|2.27.25|3.3.47|36.45.12","17":"2.3.9|2.4.7","18":"1.29.22:27|2.7.34","19":"1.27.21","20":"4.10.9|4.18.2|5.13.14:33|36.44.28","21":"75.7.8","24":"2.27.30|17.12.47|4.10.9","26":"4.14.22","28":"2.22.19","31":"50.10.10|63.9.13|71.5.18"}},{"v":["І сказав Господь Мойсеєві й Аарону, говорячи:","ось устав закону, який заповів Господь, говорячи: скажи синам Ізраїлевим, нехай приведуть тобі руду телицю без вад, у якої нема недоліків, [і] на якій не було ярма;","і віддайте її Єлеазару священику, і виведе її геть зі стану [на місце чисте], і заколють її при ньому;","і нехай візьме Єлеазар священик перстом своїм крови її й кров’ю покропить передню сторону скинії зібрання сім разів;","і спалять телицю на його очах: шкуру її і м’ясо її й кров її з нечистотою її нехай спалять;","і нехай візьме священик кедрового дерева й ісопу і нитку з червленої вовни і кине на спалювану телицю;","і нехай вимиє священик одяг свій, і обмиє тіло своє водою, і потім увійде в стан, і нечистим буде священик до вечора.","І той, хто спалював її, нехай вимиє одяг свій водою, і обмиє тіло своє водою, і нечистим буде до вечора;","і хто-небудь чистий нехай збере попіл телиці і покладе поза станом на чистому місці, і буде він зберігатися для громади синів Ізраїлевих, для води очищувальної: це жертва за гріх;","і той, хто збирав попіл телиці, нехай вимиє одяг свій, і нечистий буде до вечора. Це для синів Ізраїлевих і для прибульців, які живуть у них, нехай буде уставом вічним.","Хто доторкнеться до мертвого тіла якої-небудь людини, нечистим буде сім днів:","він повинен очистити себе цією [водою] у третій день і в сьомий день, і буде чистим; якщо ж він не очистить себе в третій і сьомий день, то не буде чистим;","усякий, хто доторкнеться до мертвого тіла якої-небудь людини померлої і не очистить себе, осквернить оселю Господа: знищиться людина та із середовища Ізраїля, бо вона не покроплена очищувальною водою, вона нечиста, ще нечистота її на ній.","Ось закон: якщо людина помре в наметі, то всякий, хто ввійде в намет, і усе, що в наметі, нечистим буде сім днів;","усяка відкрита посудина, що не обв’язана і не покрита, нечиста.","Усякий, хто доторкнеться на полі до убитого мечем, або до померлого, або до кістки людської, або до гробу, нечистим буде сім днів.","Для нечистого нехай візьмуть попелу тієї спаленої жертви за гріх і наллють на нього живої води в посудину;","і нехай хто-небудь чистий візьме ісоп, і вмочить його у воду, і покропить намет і весь посуд і людей, які знаходяться в ньому, і того, хто доторкнувся до кістки [людської], або до вбитого, або до померлого, або до гробу;","і нехай покропить чистий нечистого в третій і сьомий день, і очистить його в сьомий день; і вимиє він одежу свою, і обмиє [тіло своє] водою, і на вечір буде чистим.","Якщо ж хто буде нечистим і не очистить себе, то знищиться людина та із середовища народу, бо вона осквернила святилище Господа; очищувальною водою вона не покроплена, вона нечиста.","І нехай буде це для них уставом вічним. І той, хто кропив очищувальною водою, нехай вимиє одяг свій; і той, хто доторкнувся до очищувальної води, нечистим буде до вечора.","І все, до чого доторкнеться нечистий, буде нечистим; і людина, яка доторкнулася, буде нечистою до вечора."],"x":{"2":"75.9.13|64.5.21","3":"2.24.14|50.27.33|75.13.12","4":"75.9.13|56.1.2","6":"2.14.4","7":"2.11.24|3.8.7","9":"58.1.7|75.9.13|3.31.19:23|75.10.22","10":"1.27.21","13":"31.52.11","16":"3.31.19","18":"1.12.22|2.14.4-5","20":"75.10.26:29"}},{"v":["І прийшли сини Ізраїлеві, уся громада, в пустелю Син у перший місяць, і зупинився народ в Кадесі, і померла там Маріам і похована там.","І не було води для громади, і зібралися вони проти Мойсея й Аарона;","і нарікав народ на Мойсея і сказав: о, якби і ми померли тоді, коли померли брати наші перед Господом!","навіщо ви привели громаду Господню в цю пустелю, щоб померти тут нам і худобі нашій?","і для чого вивели ви нас з Єгипту, щоб привести нас на це негідне місце, де не можна сіяти, немає ні смоковниць, ні винограду, ні гранатових яблук, ні навіть води для пиття?","І пішов Мойсей і Аарон від народу до входу в скинію зібрання, і впали на лиця свої, і явилася їм слава Господня.","І сказав Господь Мойсеєві, говорячи:","візьми жезл і збери громаду, ти й Аарон, брат твій, і скажіть на очах їхніх скелі, і вона дасть із себе воду: і так ти виточиш їм воду зі скелі, і напоїш громаду і худобу її.","І взяв Мойсей жезл від лиця Господа, як Він повелів йому.","І зібрали Мойсей і Аарон народ до скелі, і сказав він їм: послухайте, непокірливі, хіба що нам з цієї скелі виточити для вас воду?","І підняв Мойсей руку свою і вдарив у скелю жезлом своїм двічі, і потекло багато води, і пила громада і худоба її.","І сказав Господь Мойсеєві й Аарону: за те, що ви не повірили Мені, щоб виявити святість Мою перед очима синів Ізраїлевих, не введете ви народ цей у землю, яку Я даю йому.","Це вода Мериви, біля якої ввійшли в суперечку сини Ізраїлеві з Господом, і Він явив їм святість Свою.","І послав Мойсей з Кадеса послів до царя Едомського [сказати]: так говорить брат твій Ізраїль: ти знаєш усі труднощі, що осягли нас;","батьки наші перейшли в Єгипет, і ми жили в Єгипті багато часу, і зле чинили єгиптяни з нами і батьками нашими;","і воззвали ми до Господа, і почув Він голос наш, і послав ангела, і вивів нас з Єгипту; і ось, ми в Кадесі, місті біля самої межі твоєї;","дозволь нам пройти землею твоєю: ми не підемо по полях і по виноградниках і не будемо пити води з колодязів [твоїх]; але підемо дорогою царською, не звернемо ні праворуч ні ліворуч, доки не перейдемо кордони твої.","Але Едом сказав йому: не проходь через мене, інакше я з мечем виступлю проти тебе.","І сказали йому сини Ізраїлеві: ми підемо великою дорогою, і якщо будемо пити твою воду, я і худоба моя, то буду платити за неї; тільки ногами моїми пройду, що нічого не коштує.","Але він сказав: не проходь [через мене]. І виступив проти нього Едом з численним народом і з сильною рукою.","Отже, не погодився Едом дозволити Ізраїлю пройти через його край, і Ізраїль пішов убік від нього.","І рушили сини Ізраїлеві з Кадеса, і прийшла вся громада до гори Ор.","І сказав Господь Мойсеєві та Аарону на горі Ор, біля кордону землі Едомської, говорячи:","нехай прилучиться Аарон до народу свого; бо він не ввійде в землю, яку Я даю синам Ізраїлевим, за те, що ви непокірними були велінню Моєму біля вод Мериви;","і візьми Аарона [брата твого] і Єлеазара, сина його, і зведи їх на гору Ор [перед усією громадою];","і зніми з Аарона одяг його, і зодягни в нього Єлеазара, сина його, і нехай Аарон відійде і помре там.","І зробив Мойсей так, як повелів Господь. Пішли вони на гору Ор на очах усієї громади,","і зняв Мойсей з Аарона одяг його, і зодягнув у нього Єлеазара, сина його; і вмер там Аарон на вершині гори. А Мойсей і Єлеазар зійшли з гори.","І побачила вся громада, що Аарон умер, і оплакував Аарона весь дім Ізраїлів тридцять днів."],"x":{"1":"4.1.19|1.2.4:7","2":"3.14.2","3":"1.17.2|25.105.16","4":"4.9.7","5":"1.17.3|32.2.6","6":"1.16.10","8":"3.17.10","10":"1.17.6|4.8.15|17.9.15|25.77.16|25.104.41|29.11.4|31.48.21|16.1.20|63.10.4","12":"4.1.37","13":"1.17.7|4.32.51","14":"0.25.25-26|4.2.8","16":"1.2.23|1.3.2:7|1.14.19","18":"4.2.30|62.15.28","19":"4.2.28","20":"3.21.4","21":"4.2.4","22":"3.33.37","24":"0.25.8|4.31.2","25":"3.33.38|4.32.50","29":"4.10.6"}},{"v":["Ханаанський цар Арада, який жив на південь, почувши, що Ізраїль іде дорогою від Афарима, вступив у бій з ізраїльтянами і декого з них взяв у полон.","І дав Ізраїль обітницю Господу, і сказав: якщо віддаси народ цей в руки мої, то накладу закляття [на них і] на міста їхні.","Господь почув голос Ізраїля і віддав хананеїв у руки його, і він наклав закляття на них і на міста їхні і нарік ім’я місцю тому: Хорма*.","Від гори Ор вирушили вони шляхом до Червоного моря, щоб обійти землю Едома. І став слабкодухим народ на шляху,","і говорив народ проти Бога і проти Мойсея: навіщо ви вивели нас з Єгипту, щоб померти [нам] у пустелі, бо тут нема ні хліба, ні води, і душі нашій обридла ця негідна їжа.","І послав Господь на народ отруйних зміїв, що жалили народ, і померло безліч народу з [синів] Ізраїлевих.","І прийшов народ до Мойсея і сказав: згрішили ми, що говорили проти Господа і проти тебе; помолися Господу, щоб Він відігнав від нас зміїв. І помолився Мойсей [Господу] за народ.","І сказав Господь Мойсеєві: зроби собі [мідного] змія і вистав його на прапорі, і [якщо вжалить змій кого-небудь], ужалений, глянувши на нього, залишиться живим.","І зробив Мойсей мідного змія і виставив його на прапорі, і коли змій жалив людину, вона, глянувши на мідного змія, залишалася живою.","І рушили сини Ізраїлеві і зупинилися в Овофі;","й рушили з Овофа і зупинилися в Ійє-Аваримі, в пустелі, що навпроти Моава, на схід сонця;","звідти рушили, і зупинилися в долині Заред;","вирушивши звідси, зупинилися в тій частині Арнона в пустелі, що лежить поза межами Аморрея, бо Арнон кордон Моава, між Моавом і Аморреєм.","Тому і сказано в книзі воєн Господніх:","Вагеб у Суфі і потоки Арнона, і верхів’я потоків, що схиляється до Шебет-Ару і прилягає до меж Моава.","Звідси [рушили] до Беер*; це той колодязь, про який Господь сказав Мойсею: збери народ, і дам їм води.","Тоді заспівав Ізраїль пісню цю: наповнюйся, колодязь, оспівуйте його;","колодязь, який викопали князі, вирили вожді народу з законодавцем жезлами своїми. З пустелі [рушили] в Матанну,","з Матанни в Нагалиїл, з Нагалиїла у Вамоф,","з Вамофа у Гай, що в землі Моава, на вершині гори Фасги, зверненої лицем до пустелі.","І послав Ізраїль послів до Сигона, царя Аморрейського, [з пропозицією мирною,] щоб сказати:","дозволь мені пройти землею твоєю; [ми підемо дорогою,] не будемо заходити на поля і виноградники, не будемо пити води з колодязів [твоїх], а підемо шляхом царським, поки не перейдемо меж твоїх.","Але Сигон не дозволив Ізраїлю йти через свій край; і зібрав Сигон весь народ свій і виступив проти Ізраїля в пустелі, і дійшов до Іааци, і воював з Ізраїлем.","І вразив його Ізраїль мечем і взяв у володіння землю його від Арнона до Іавока, до меж аммонитських, бо міцними були межі аммонитян;","і взяв Ізраїль всі міста ці, і жив Ізраїль у всіх містах аморрейських, в Есевоні й у всіх залежних від нього;","тому що Есевон було місто Сигона, царя Аморрейського, і він воював з попереднім царем Моавитським і взяв з руки його всю землю його до Арнона.","Тому говорять при?точники: йдіть у Есевон, нехай влаштують і утвердять місто Сигона;","бо вогонь вийшов з Есевона, полум’я з міста Сигонового, і пожер Ар-Моав і тих, що володіють висотами Арнона.","Горе тобі, Моав! загинув ти, народ Хамоса! Розбіглися сини його, і дочки його зробилися полонянками Аморрейського царя Сигона;","ми вразили їх стрілами; загинув Есевон до Дивона, ми спустошили їх до Нофи, яка поблизу Медеви.","І жив Ізраїль у землі Аморрейській.","І послав Мойсей видивитися Іазер, і взяли [його і] селища, що залежать від нього, і прогнали аморреїв, що були в них.","І повернули і пішли до Васана. І виступив проти них Ог, цар Васанський, сам і весь народ його, на битву біля Едреї.","І сказав Господь Мойсеєві: не бійся його, бо Я віддам його і весь народ його і всю землю його в руки твої, і вчиниш з ним, як вчинив із Сигоном, царем Аморрейським, що жив у Есевоні.","І вразили вони його і синів його і весь народ його, так що жодного не залишилося [живим], і оволоділи землею його."],"x":{"1":"3.33.40","2":"2.27.28","3":"5.2.9","4":"3.11.1","5":"4.6.16","6":"29.16.5|63.10.9","7":"1.8.8","8":"53.3.14","9":"11.18.4|53.3.14","10":"3.33.43","11":"3.33.44","12":"4.2.13","13":"6.11.13","15":"31.15.8","16":"3.20.8","18":"4.33.21","21":"4.2.26|6.11.19|17.9.22","22":"3.20.17","23":"4.2.32","24":"4.31.4|5.9.10|5.24.8|6.11.21|25.134.11|40.2.9|16.1.11","28":"32.48.45","29":"10.11.7","30":"31.15.2|32.48.8","33":"4.3.1|4.29.7","34":"25.134.11"},"n":{"3":["Закляття."],"16":["Колодязь."]}},{"v":["І вирушили сини Ізраїлеві, і зупинилися на рівнинах Моава, при Йордані, навпроти Єрихона.","І бачив Валак, син Сепфорів, усе, що зробив Ізраїль аморреям;","і дуже боялися моавитяни народу цього, тому що він був численний; і злякалися моавитяни синів Ізраїлевих.","І сказали моавитяни старійшинам мадіамським: цей народ поїдає тепер усе навколо нас, як віл поїдає траву польову. Валак же, син Сепфорів, був царем моавитян у той час.","І послав він послів до Валаама, сина Веорового, у Пефор, що на ріці Євфраті, в землі синів народу його, щоб покликати його і сказати: ось, народ вийшов з Єгипту і покрив лице землі, і живе він поряд зі мною;","отже, прийди, прокляни мені народ цей, тому що він сильніший за мене: можливо, тоді я зможу вразити його і вигнати його з землі; я знаю, що кого ти благословиш, той благословенний, і кого ти проклянеш, той проклятий.","І пішли старійшини моавитські і старійшини мадіамські, з подарунками в руках за волхвування, і прийшли до Валаама, і переказали йому слова Валакові.","І сказав він їм: переночуйте тут ніч, і дам вам відповідь, як скаже мені Господь. І залишилися старійшини моавитські у Валаама.","І прийшов Бог до Валаама і сказав: які це люди в тебе?","Валаам сказав Богу: Валак, син Сепфорів, цар Моавитський, прислав [їх] до мене [сказати]:","ось, народ вийшов з Єгипту і покрив лице землі, [і живе поряд зі мною]; отже, прийди, прокляни мені його; можливо, тоді я буду в стані воювати з ним і вигнати його [із землі].","І сказав Бог Валааму: не ходи з ними, не проклинай народу цього, бо він благословенний.","І встав Валаам зранку і сказав князям Валаковим: ідіть у землю вашу, бо не хоче Господь дозволити мені йти з вами.","І встали князі моавитські, і прийшли до Валака, і сказали [йому]: не погодився Валаам іти з нами.","Валак послав ще князів, більших і славніших за тих.","І прийшли вони до Валаама і сказали йому: так говорить Валак, син Сепфорів: не відмовся прийти до мене;","я виявлю до тебе велику шану і зроблю [тобі] все, що скажеш мені; прийди ж, прокляни мені народ цей.","І відповів Валаам і сказав рабам Валаковим: хоча б Валак давав мені повний свій дім срібла і золота, не можу переступити повеління Господа, Бога мого, і зробити що-небудь мале або велике [за своєю волею];","втім, залишіться тут і ви на ніч, і я дізнаюся, що ще скаже мені Господь.","І прийшов Бог до Валаама вночі і сказав йому: якщо люди ці прийшли кликати тебе, встань, піди з ними; але тільки роби те, що Я буду говорити тобі.","Валаам встав уранці, осідлав ослицю свою і пішов із князями моавитськими.","І запалав гнів Божий за те, що він пішов, і став ангел Господній на дорозі, щоб перешкодити йому. Він їхав на ослиці своїй і з ним двоє слуг його.","І побачила ослиця ангела Господнього, що стоїть на дорозі з оголеним мечем у руці, і звернула ослиця з дороги, і пішла на поле; а Валаам став бити ослицю, щоб повернути її на дорогу.","І став ангел Господній на вузькій дорозі, між виноградниками, де з одного боку стіна і з другого боку стіна.","Ослиця, побачивши ангела Господнього, притулилася до стіни і притиснула ногу Валаама до стіни; і він знову став бити її.","Ангел Господній знову перейшов і став у вузькому місці, де нікуди звернути, ні праворуч, ні ліворуч.","Ослиця, побачивши ангела Господнього, лягла під Валаамом. І запалав гнів Валаама, і став він бити ослицю палицею.","І відкрив Господь уста ослиці, і вона сказала Валааму: що я тобі зробила, що ти б’єш мене ось уже третій раз?","Валаам сказав ослиці: за те, що ти наглумилася з мене; якби у мене був у руці меч, то я зараз же убив би тебе.","Ослиця ж сказала Валааму: чи не я твоя ослиця, на якій ти їздив спочатку до цього дня чи мала я звичку так поводитися з тобою? Він сказав: ні.","І відкрив Господь очі Валааму, і побачив він ангела Господнього, що стоїть на дорозі з оголеним мечем у руці, і схилився, і впав на лице своє.","І сказав йому ангел Господній: за що ти бив ослицю твою ось уже три рази? Я вийшов, щоб перешкодити [тобі], тому що шлях [твій] неправий переді Мною;","і ослиця, побачивши Мене, звернула від Мене ось уже тричі; якби вона не звернула від Мене, то Я убив би тебе, а її залишив би живою.","І сказав Валаам ангелові Господньому: згрішив я, тому що не знав, що Ти стоїш проти мене на дорозі; отже, якщо це неприємно в очах Твоїх, то я повернусь.","І сказав ангел Господній Валааму: піди з людьми цими, тільки говори те, що Я буду говорити тобі. І пішов Валаам із князями Валаковими.","Валак, почувши, що йде Валаам, вийшов назустріч йому в місто моавитське, яке на кордоні біля Арнона, що біля самої межі.","І сказав Валак Валааму: чи не посилав я до тебе, кликати тебе? чому ти не йшов до мене? невже я насправді не можу вшанувати тебе?","І сказав Валаам Валаку: ось, я й прийшов до тебе, але чи можу я що від себе сказати? що вкладе Бог в уста мої, те і буду говорити.","І пішов Валаам з Валаком і прийшли в Кириаф-Хуцоф.","І заколов Валак волів і овець, і послав до Валаама і князів, що були з ним.","На другий день ранком Валак узяв Валаама і звів його на висоти Ваалові, щоб він побачив звідти частину народу."],"x":{"1":"3.33.48","2":"6.11.25","3":"9.8.2","4":"3.23.24","5":"4.23.4|5.24.9","6":"3.23.25|43.6.5","7":"57.2.15|61.1.11","11":"4.23.5","18":"3.24.13","28":"57.2.16|61.1.11","31":"5.5.13"}},{"v":["І сказав Валаам Валаку: побудуй мені тут сім жертовників і приготуй мені сім тельців і сім баранів.","Валак зробив так, як говорив Валаам, і принесли Валак і Валаам по тельцю і барану на кожному жертовнику.","І сказав Валаам Валаку: постій біля всепалення твого, а я піду; може, Господь вийде мені назустріч, і що Він відкриє мені, я оголошу тобі. І [залишився Валак біля всепалення свого, а Валаам] пішов на підвищене місце [запитати Бога].","І зустрівся Бог з Валаамом, і сказав йому [Валаам]: сім жертовників влаштував я і приніс тельця і барана на кожному жертовнику.","І вклав Господь слово в уста Валаамові і сказав: повернися до Валака і так говори.","І повернувся до нього, і ось він стоїть біля всепалення свого, він і всі князі моавитські. [І був на ньому Дух Божий.]","І промовив притчу свою і сказав: з Месопотамії привів мене Валак, цар Моава, від гір східних: прийди, прокляни мені Якова, прийди, проголоси зло на Ізраїля!","Як прокляну я? Бог не проклинає його. Як проголошу зло? Господь не проголошує [на нього] зла.","З вершини скель бачу я його, і з пагорбів дивлюся на нього: ось, народ живе окремо і між народами не числиться.","Хто перелічить пісок Якова і число четвертої частини Ізраїлю? Нехай помре душа моя смертю праведників, і нехай буде кончина моя, як їх!","І сказав Валак Валааму: що ти зі мною робиш? я взяв тебе, щоб проклясти ворогів моїх, а ти, ось, благословляєш?","І відповів він і сказав: чи не повинен я достеменно сказати те, що вкладає Господь в уста мої?","І сказав йому Валак: піди зі мною на інше місце, з якого ти побачиш його, але тільки частину його побачиш, а всього його не побачиш; і прокляни мені його звідти.","І взяв його на місце сторожі, на вершину гори Фасги, і побудував сім жертовників, і приніс по тельцю і барану на кожному жертовнику.","І сказав [Валаам] Валаку: постій тут біля всепалення твого, а я [піду] туди назустріч [Богу].","І зустрівся Господь з Валаамом, і вклав слово в уста його, і сказав: повернися до Валака і так говори.","І прийшов до нього, і ось, він стоїть біля всепалення свого, і з ним [усі] князі моавитські. І сказав йому Валак: що говорив Господь?","Він промовив притчу свою і сказав: встань, Валаку, і послухай, мене, сину Сепфорів.","Бог не людина, щоб Йому говорити неправду, і не син людський, щоб Йому змінюватися. Чи Він скаже і не зробить? буде говорити і не виконає?","Ось, почав я благословляти, бо Він благословив, і я не можу змінити цього.","Не видно біди в Якові, і не помітно нещастя в Ізраїлі; Господь, Бог його, з ним, і трубний царський звук у нього;","Бог вивів їх з Єгипту, швидкість єдинорога у нього;","нема чаклунства в Якові і нема ворожіння в Ізраїлі. У свій час скажуть про Якова і про Ізраїль: ось що творить Бог!","Ось, народ як левиця встає і як лев піднімається; не ляже, поки не з’їсть здобичі і не нап’ється крови убитих.","І сказав Валак Валааму: ні клясти не кляни його, ні благословляти не благословляй його.","І відповів Валаам і сказав Валаку: чи не говорив я тобі, що я буду робити все те, що скаже мені Господь?","І сказав Валак Валааму: піди, я візьму тебе на інше місце; можливо, угодно буде Богу, і звідти проклянеш мені його.","І взяв Валак Валаама на вершину Фегора, поверненого до пустелі.","І сказав Валаам Валаку: побудуй мені тут сім жертовників і приготуй мені тут сім тельців і сім баранів.","І зробив Валак, як сказав Валаам, і приніс по тельцю і барану на кожному жертовнику."],"x":{"7":"4.23.4","8":"5.24.10","9":"4.33.28","10":"0.13.16|10.19.4","12":"4.32.31","14":"4.3.27","19":"8.15.29|49.3.6|73.1.2","21":"25.54.11|32.50.20","22":"3.24.8","24":"0.49.9","25":"3.22.6","28":"3.25.3"}},{"v":["Валаам побачив, що Господу вгодно благословляти Ізраїля, і не пішов, як раніше, для волхвування, але обернувся лицем своїм до пустелі.","І глянув Валаам і побачив Ізраїля, що стояв за колінами своїми, і був на ньому Дух Божий.","І промовив він притчу свою і сказав: говорить Валаам, син Веорів, говорить муж з відкритими очима,","говорить той, хто чує слова Божі, який бачить видіння Всемогутнього; падає, але відкриті очі його:","які прекрасні намети твої, Якове, оселі твої, Ізраїлю!","розстилаються вони, як долини, як сади біля річки, як дерева алое, насаджені Господом, як кедри біля вод;","поллється вода з відер його, і сі?м’я його буде, як великі води, перевершить Агага цар його і піднесеться царство його.","Бог вивів його з Єгипту, швидкість єдинорога в нього, пожирає народи, ворожі йому, роздроблює кістки їх і стрілами своїми уражає [ворога].","Схилився, лежить як лев і як левиця, хто підніме його? Той, хто благословляє тебе, благословенний, і хто проклинає тебе, проклятий!","І запалав гнів Валака на Валаама, і сплеснув він руками своїми, і сказав Валак Валааму: я покликав тебе проклясти ворогів моїх, а ти благословляєш їх ось уже втретє;","отже, тікай у своє місце; я хотів ушанувати тебе, але ось, Господь позбавляє тебе чести.","І сказав Валаам Валаку: чи не говорив я послам твоїм, яких ти посилав до мене:","«хоча б давав мені Валак повний свій будинок срібла і золота, не можу переступити повеління Господнього, щоб зробити що-небудь добре чи зле за своєю волею: що скаже Господь, те й буду говорити»?","Отже, ось, я йду до народу свого; піди, я провіщу тобі, що зробить народ цей з народом твоїм з часом.","І промовив притчу свою і сказав: говорить Валаам, син Веорів, говорить муж з відкритими очима,","говорить той, хто чує слова Божі, хто має видіння від Всевишнього, хто бачить видіння Всемогутнього, падає, але відкриті очі його.","Бачу Його, але нині ще немає; бачу Його, але не близько. Сходить зірка від Якова і постає жезл від Ізраїля, і вражає князів Моава і розтрощує всіх синів Сифових.","Едом буде під володінням, Сеїр буде під володінням ворогів своїх, а Ізраїль явить силу свою.","Той, хто вийде від Якова, заволодіє і знищить те, що залишилося від міста.","І побачив він Амалика, і промовив притчу свою і сказав: перший з народів Амалик, але кінець його — загибель.","І побачив він кенеїв, і промовив притчу свою, і сказав: міцне житло твоє, і на скелі покладене гніздо твоє;","але зруйнований буде Каїн, і недовго до того, що Ассур поведе тебе в полон.","І [побачивши Ога,] промовив притчу свою і сказав: горе, [горе,] хто уціліє, коли наведе це Бог!","прийдуть кораблі від Киттима, й упокорять Ассура, й упокорять Евера; але і їм загибель!","І встав Валаам і пішов назад у своє місце, а Валак також пішов своєю дорогою."],"x":{"1":"3.23.3","5":"5.24.10","6":"25.1.3|32.17.8","8":"3.23.22","9":"0.49.9","13":"3.22.18","14":"3.25.1-2|3.31.16|76.2.14","17":"50.2.2|0.49.10|9.8.2","18":"9.8.14|0.36.8","19":"62.9.5|64.10.5|76.19.6","20":"4.25.19","21":"6.1.16|8.15.6","24":"37.11.30","25":"3.31.8"}},{"v":["І жив Ізраїль у Ситтимі, і почав народ блудодіяти з дочками Моава,","і запрошували вони народ до жертв богам своїм, і їв народ [жертви їх] і кланявся богам їхнім.","І приліпився Ізраїль до Ваал-Фегора. І запалав гнів Господній на Ізраїля.","І сказав Господь Мойсеєві: візьми всіх начальників народу і повісь їх Господу перед сонцем, і відвернеться від Ізраїля лютість гніву Господнього.","І сказав Мойсей суддям Ізраїлевим: убийте кожен людей своїх, що приліпилися до Ваал-Фегора.","І ось, хтось із синів Ізраїлевих прийшов і привів до братів своїх мадіанитянку, на очах Мойсея й на очах усієї громади синів Ізраїлевих, коли вони плакали при вході у скинію зібрання.","Финеєс, син Єлеазара, сина Аарона священика, побачивши це, встав із середовища громади і взяв у руку свою спис,","і ввійшов слідом за ізраїльтянином у спальню і проколов їх обох, ізраїльтянина і жінку в утробу її: і припинилось ураження синів Ізраїлевих.","Померлих же від ураження було двадцять чотири тисячі.","І сказав Господь Мойсеєві, говорячи:","Финеєс, син Єлеазара, сина Аарона священика, відвернув гнів Мій від синів Ізраїлевих, возревнувавши за Мене серед них, і Я не знищив синів Ізраїлевих у ревності Моїй;","тому скажи: ось, Я даю йому Мій завіт миру,","і буде він йому і нащадкам його після нього завітом священства вічного, за те, що він показав ревність за Бога свого і заступив синів Ізраїлевих.","Ім’я вбитого ізраїльтянина, який був убитий з мадіанитянкою, було Зимри, син Салу, начальник покоління Симеонового;","а ім’я вбитої мадіанитянки Хазва; вона була дочкою Цура, начальника Оммофа, племені мадіамського.","І сказав Господь Мойсеєві, говорячи:","ворогуйте з мадіанитянами, й уражайте їх,","тому що вони вороже вчинили з вами в підступництві своєму, спокусивши вас Фегором і Хазвою, дочкою начальника мадіамського, сестрою своєю, вбитою в день ураження за Фегора."],"x":{"1":"3.31.16|63.10.8|76.2.14","3":"5.22.17|25.105.28","4":"4.4.3","7":"25.105.30","9":"63.10.8","12":"30.45.29","13":"21.2.54","15":"3.31.8","17":"3.31.2"}},{"v":["Після цього ураження сказав Господь Мойсеєві та Єлеазару, сину Аарона, священикові, говорячи;","порахуйте всю громаду синів Ізраїлевих від двадцяти років і вище, за сімействами їх, усіх придатних для війни у Ізраїля.","І сказав їм Мойсей і Єлеазар священик на рівнинах моавитських біля Йордану, навпроти Єрихона, говорячи:","порахуйте всіх від двадцяти років і вище, як повелів Господь Мойсеєві і синам Ізраїлевим, які вийшли з землі Єгипетської:","Рувим, первісток Ізраїля. Сини Рувима: від Ханоха покоління Ханохове, від Фаллу покоління Фаллуєве,","від Хецрона покоління Хецронове, від Харми покоління Хармиєве;","ось покоління Рувимові; і пораховано їх сорок три тисячі сімсот тридцять.","І сини Фаллуя: Елиав.","Сини Елиава: Немуїл, Дафан і Авирон. Це ті Дафан і Авирон, що були покликані в зібрання, які вчинили підбурення проти Мойсея й Аарона разом зі спільниками Корея, коли ці підбурювали проти Господа;","і розверзла земля уста свої, і поглинула їх і Корея; разом з ними померли і спільники їхні, коли вогонь пожер двісті п’ятдесят чоловік, і стали вони в знамення;","але сини Кореєві не померли.","Сини Симеона за поколіннями їх: від Немуїла покоління Немуїлове, від Ямина покоління Яминове, від Яхина покоління Яхинове,","від Зари покоління Зарине, від Саула покоління Саулове;","Ось покоління Симеонові [при підрахуванні їх]: двадцять дві тисячі двісті.","Сини Гада за поколіннями їх: від Цефона покоління Цефонове, від Хаггія покоління Хаггієве, від Шунія покоління Шунієве,","від Ознія покоління Ознієве, від Ерія покоління Ерієве,","від Арода покоління Ародове, від Арелія покоління Арелієве;","від покоління синів Гадових, після підрахування їх: сорок тисяч п’ятсот.","Сини Іуди: Ір і Онан, [Шела, Фарес і Зара]; але Ір і Онан померли в землі Ханаанській;","і були сини Іуди за поколіннями їх: від Шели покоління Шелине, від Фареса покоління Фаресове, від Зари покоління Зарине;","і були сини Фаресові: від Есрома покоління Есромове, від Хамула покоління Хамулове;","ось покоління Іудині, після підрахування їх: сімдесят шість тисяч п’ятсот.","Сини Іссахарові за поколіннями їх: від Фоли покоління Фолине, від Фуви покоління Фувине,","від Іашува покоління Іашувове, від Шимрона покоління Шимронове;","ось покоління Іссахарові, після підрахування їх: шістдесят чотири тисячі триста.","Сини Завулонові за поколіннями їх: від Середа покоління Середове, від Елона покоління Елонове, від Іахлеїла покоління Іахлеїлове;","ось покоління Завулонові, після підрахування їх: шістдесят тисяч п’ятсот.","Сини Йосифа за поколіннями їх: Манассія і Єфрем.","Сини Манассіїні: від Махира покоління Махирове; від Махира народився Галаад, від Галаада покоління Галаадове.","Ось сини Галаадові: від Ієзера покоління Ієзерове, від Хелека покоління Хелекове,","від Асриїла покоління Асриїлове, від Шехема покоління Шехемове,","від Шемиди покоління Шемидине, від Хефера покоління Хеферове.","У Салпаада, сина Хеферового, не було синів, а тільки дочки; ім’я дочок Салпаадових: Махла, Ноа, Хогла, Милка і Фирца.","Ось покоління Манассіїні; а підраховано їх п’ятдесят дві тисячі сімсот.","Ось сини Єфремові за поколіннями їх: від Шутели покоління Шутелине, від Бехера покоління Бехерове, від Тахана покоління Таханове;","і ось сини Шутели: від Арана покоління Аранове;","ось покоління синів Єфремових, після підрахування їх: тридцять дві тисячі п’ятсот. Ось сини Йосифові за поколіннями їх.","Сини Веніамінові за поколіннями їх: від Бели покоління Белине, від Ашбела покоління Ашбелове, від Ахирама покоління Ахирамове,","від Шефуфама покоління Шефуфамове, від Хуфама покоління Хуфамове;","і були сини Бели: Ард і Нааман; [від Арда] покоління Ардове, від Наамана покоління Нааманове;","ось сини Веніамінові за поколіннями їх; а підраховано їх сорок п’ять тисяч шістсот.","Ось сини Данові за поколіннями їх: від Шухама покоління Шухамове; ось сімейства Данові за поколіннями їх.","І всіх поколінь Шухама, після підрахування їх: шістдесят чотири тисячі чотириста.","Сини Асирові за поколіннями їх: від Імни покоління Імнине, від Ішви покоління Ішвине, від Верії покоління Веріїне;","від синів Верії, від Хевера покоління Хеверове, від Малхиїла покоління Малхиїлове;","ім’я дочки Асирової Сара;","ось покоління синів Асирових, після підрахування їх: п’ятдесят три тисячі чотириста.","Сини Неффалима за поколіннями їх: від Іахцеїла покоління Іахцеїлове, від Гунія покоління Гунієве,","від Ієцера покоління Ієцерове, від Шиллема покоління Шиллемове;","ось покоління Неффалимові за поколіннями їх; підраховано ж їх сорок п’ять тисяч чотириста.","Ось число синів Ізраїлевих, що ввійшли у підрахунок: шістсот одна тисяча сімсот тридцять.","І сказав Господь Мойсеєві, говорячи:","цим у наділ слід розділити землю за числом імен;","хто численніший, тому дай наділ більший; а хто менш численний, тому дай наділ менший: кожному слід дати наділ відповідно до числа тих, що ввійшли до підрахунку;","за жеребом слід розділити землю, за іменами колін батьків їх повинні вони одержати наділи;","за жеребом слід розділити їм наділи їх, як численним, так і нечисленним.","Ці є левити, що ввійшли до підрахунку, за поколіннями їх: від Гирсона покоління Гирсонове, від Каафа покоління Каафове, від Мерарі покоління Мерарине.","Ось покоління Левіїні: покоління Ливнієве, покоління Хевронове, покоління Махлієве, покоління Мушієве, покоління Кореєве. Від Каафа народився Амрам.","Ім’я дружини Амрамової Іохаведа, дочка Левіїна, яку народила дружина Левіїна в Єгипті, а вона Амраму народила Аарона, Мойсея і Маріам, сестру їхню.","І народилися в Аарона Надав і Авиуд, Єлеазар та Іфамар;","але Надав і Авиуд померли, коли принесли чужий вогонь перед Господом [у пустелі Синайській].","І було підраховано двадцять три тисячі всіх чоловічої статі, від одного місяця і вище; бо вони не були пораховані разом із синами Ізраїлевими, тому що не дано їм наділу серед синів Ізраїлевих.","Ось підраховані Мойсеєм і Єлеазаром священиком, які рахували синів Ізраїлевих на рівнинах моавитських біля Йордану, навпроти Єрихона;","у числі їх не було жодної людини з перелічених Мойсеем і Аароном священиком, які рахували синів Ізраїлевих у пустелі Синайській;","бо Господь сказав їм, що помруть вони в пустелі, — і не залишилося з них нікого, крім Халева, сина Ієфонніїного, та Ісуса, сина Навина."],"x":{"2":"3.1.2","3":"3.33.50","5":"0.46.8","9":"3.16.1","10":"3.16.31","11":"3.16.32","12":"0.46.10","19":"0.38.3-4","20":"0.38.5","21":"0.46.12|12.2.5","23":"0.46.13","26":"0.46.14","29":"5.17.1","33":"5.17.3","57":"0.46.11|1.6.16|3.3.17|12.6.1","59":"1.2.2|1.6.20|12.23.13","61":"2.10.1|3.3.4|12.24.2","65":"3.14.28|3.32.10|4.1.35|25.105.26|63.10.5"}},{"v":["І прийшли дочки Салпаада, сина Хеферового, сина Галаадового, сина Махирового, сина Манассіїного з покоління Манассії, сина Йосифового, і ось імена дочок його: Махла, Ноа, Хогла, Милка і Фирца;","і стали перед Мойсеєм і перед Єлеазаром священиком, і перед князями і перед усією громадою, біля входу в скинію зібрання, і сказали:","батько наш помер у пустелі, і він не був у числі спільників, які зібралися проти Господа зі збіговиськом Кореєвим, але за свій гріх помер, і синів у нього не було;","за що зникати імені батька нашого з племені його, бо немає у нього сина? дай нам наділ серед братів батька нашого.","І представив Мойсей справу їхню Господу.","І сказав Господь Мойсеєві:","правду говорять дочки Салпаадові; дай їм спадкоємний наділ серед братів батька їхнього і передай їм наділ батька їх;","і синам Ізраїлевим оголоси і скажи: якщо хто помре, не маючи у себе сина, то передавайте наділ його дочці його;","якщо ж немає у нього дочки, передавайте наділ його братам його;","якщо ж немає у нього братів, віддайте наділ його братам батька його;","якщо ж немає братів батька його, віддайте наділ його близькому його родичеві з покоління його, щоб він успадкував його; і нехай буде це для синів Ізраїлевих поставлено в закон, як повелів Господь Мойсеєві.","І сказав Господь Мойсеєві: зійди на цю гору Аварим, [яка по цей бік Йордану, на цю гору Ново,] і подивися на землю [Ханаанську], яку Я даю синам Ізраїлевим [у володіння];","і коли подивишся на неї, прилучися до народу свого і ти, як прилучився Аарон, брат твій, [на горі Ор];","тому що ви не послухалися повеління Мого в пустелі Син, під час розбрату в громаді, щоб явити перед очима їхніми святість Мою при водах. [Це води Мериви при Кадесі в пустелі Син.]","І сказав Мойсей Господу, говорячи:","нехай поставить Господь, Бог духів усякої плоті, над цією громадою людину,","яка виходила б перед ними і яка входила б перед ними, яка виводила б їх і яка приводила б їх, щоб не залишилася громада Господня, як вівці, в яких немає пастиря.","І сказав Господь Мойсеєві: візьми собі Ісуса, сина Навина, людину, в якій є Дух, і поклади на нього руку твою,","і постав його перед Єлеазаром священиком і перед усією громадою, і дай йому настанову перед очима їх,","і дай йому від слави твоєї, щоб слухала його вся громада синів Ізраїлевих;","і буде він звертатися до Єлеазара священика і запитувати його про рішення, через урим перед Господом; і за його словом повинні виходити, і за його словом повинні входити він і всі сини Ізраїлеві з ним і вся громада.","І зробив Мойсей, як повелів йому Господь [Бог], і взяв Ісуса, і поставив його перед Єлеазаром священиком і перед усією громадою;","і поклав на нього руки свої і дав йому настанову, як говорив Господь через Мойсея."],"x":{"1":"3.36.2","3":"3.16.1:30","8":"18.6.12","12":"4.32.48-49","14":"4.32.51","18":"4.3.21|4.34.9|0.48.14|3.8.10","20":"4.34.9","21":"1.28.30"}},{"v":["І сказав Господь Мойсеєві, говорячи:","накажи синам Ізраїлевим і скажи їм: пильнуйте, щоб приношення Моє, хліб Мій у жертву Мені, у приємні пахощі Мені, приносилося Мені у свій час.","І скажи їм: ось жертва, яку ви повинні приносити Господу: два агнці однолітніх без вад на день, у всепалення постійне;","одного агнця принось ранком, а другого агнця принось увечері;","і в приношення хлібне [принось] десяту частину ефи пшеничного борошна, змішаного з чвертю гина вичавленого єлею;","це — всепалення постійне, яке звершене було біля гори Синай, у приємні пахощі, у жертву Господу;","й узливання при ній чверть гина на одного агнця: на святому місці зливай узливання, вино Господу.","Другого агнця принось увечері, з таким хлібним приношенням, як вранці, і з таким самим узливанням при ньому принось його в жертву, у приємні пахощі Господу.","А в суботу [приносьте] двох агнців однолітніх без вад, і в приношення хлібне дві десятих частини ефи пшеничного борошна, змішаного з єлеєм, і узливання при ньому:","це — суботнє всепалення в кожну суботу, зверх постійного всепалення й узливання при ньому.","І в новомісяччя ваші приносьте всепалення Господу: із великої худоби двох тельців, одного барана і сім однолітніх агнців без вад,","і три десятих частини ефи пшеничного борошна, змішаного з єлеєм, у приношення хлібне на одного тельця, і дві десятих частини ефи пшеничного борошна, змішаного з єлеєм, у приношення хлібне на барана,","і по десятій частині ефи пшеничного борошна, змішаного з єлеєм, у приношення хлібне на кожного агнця; це — всепалення, приємні пахощі, жертва Господу;","й узливання при них повинно бути півгина вина на тельця, третина гина на барана і чверть гина на агнця; це всепалення в кожне новомісяччя в усі місяці року.","І одного козла приносьте Господу в жертву за гріх; зверх всепалення постійно слід приносити його з узливанням його.","У перший місяць, у чотирнадцятий день місяця — Пасха Господня.","І в п’ятнадцятий день цього місяця свято; сім днів слід їсти опрісноки.","У перший день [нехай буде у вас] священне зібрання; жодної роботи не виконуйте;","і приносьте жертву, всепалення Господу: з великої худоби двох тельців, одного барана і сім однолітніх агнців; без вад вони повинні бути у вас;","і при них у приношення хлібне приносьте пшеничного борошна, змішаного з єлеєм, три десятих частини ефи на кожного тельця, і дві десятих частини ефи на барана,","і по десятій частині ефи принось на кожного з семи агнців,","і одного козла в жертву за гріх, для очищення вас;","зверх ранкового всепалення, яке є всепаленням постійним, приносьте це.","Так приносьте і в кожен із семи днів; це хліб, жертва, приємні пахощі Господу; зверх всепалення постійного й узливання його, слід приносити це.","І в сьомий день нехай буде у вас священне зібрання; ніякої роботи не виконуйте.","І в день перших плодів, коли приносите Господу нове приношення хлібне в седмиці ваші, нехай буде у вас священне зібрання; ніякої роботи не виконуйте;","і приносьте всепалення в приємні пахощі Господу: з великої худоби двох тельців, одного барана і сім однолітніх агнців [без вад],","і при них у приношення хлібне пшеничного борошна, змішаного з єлеєм, три десятих частини ефи на кожного тельця, дві десяті частини ефи на барана,","і по десятій частині ефи на кожного з семи агнців,","і одного козла [у жертву за гріх], для очищення вас;","зверх постійного всепалення і хлібного приношення при ньому, приносьте [це Мені] з узливанням їх; без вад вони повинні бути у вас."],"x":{"2":"2.3.11|2.21.6","3":"1.29.38","5":"1.16.36","11":"31.1.13|31.66.23|68.2.16","14":"3.10.10","15":"3.29.5","16":"1.12.18|2.23.5","17":"1.12.15|4.16.3","19":"4.16.2|13.35.7","21":"1.16.36","26":"2.23.15-16"}},{"v":["У сьомий місяць, у перший [день] місяця, нехай буде у вас священне зібрання; ніякої роботи не виконуйте; нехай буде це у вас день трубного звуку;","і приносьте всепалення в приємні пахощі Господу: одного тельця, одного барана, сім однолітніх агнців, без вад,","і при них у приношення хлібне пшеничного борошна, змішаного з єлеєм, три десятих частини ефи на тельця, дві десятих части ефи на барана,","й одну десяту частину ефи на кожного з семи агнців,","і одного козла в жертву за гріх, для очищення вас,","зверх новомісячного всепалення і хлібного приношення його, і зверх постійного всепалення і хлібного приношення його, й узливань їх, за уставом, у приємні пахощі Господу.","І в десятий [день] цього сьомого місяця нехай буде у вас священне зібрання: смиряйте тоді душі ваші і ніякої справи не робіть;","і приносьте всепалення Господу в приємні пахощі: одного тельця, одного барана, сім однолітніх агнців; без вад нехай будуть вони у вас;","і при них у приношення хлібне пшеничного борошна, змішаного з єлеєм, три десятих частини ефи на тельця, дві десятих частини ефи на барана,","і по десятій частині ефи на кожного з семи агнців,","і одного козла в жертву за гріх, [для очищення вас,] зверх жертви за гріх, що приноситься в день очищення, і зверх всепалення постійного і хлібного приношення його, й узливання їх, [за уставом принесених у приємні пахощі, у жертву Господу].","І в п’ятнадцятий день сьомого місяця нехай буде у вас священне зібрання; ніякої роботи не виконуйте і святкуйте свято Господнє сім днів;","і приносьте всепалення, жертву, приємні пахощі Господу: тринадцять тельців, двох баранів, чотирнадцять однолітніх агнців; без вад нехай будуть вони;","і при них у приношення хлібне пшеничного борошна, змішаного з єлеєм, три десятих частини ефи на кожного з тринадцяти тельців, дві десятих частини ефи на кожного з двох баранів,","і по десятій частині ефи на кожного з чотирнадцяти агнців,","і одного козла в жертву за гріх, зверх всепалення постійного і хлібного приношення його й узливання його.","І в другий день дванадцять тельців, двох баранів, чотирнадцять однолітніх агнців, без вад,","і при них приношення хлібне й узливання для тельців, баранів і агнців, за числом їх, за уставом,","і одного козла в жертву за гріх, зверх всепалення постійного і хлібного приношення й узливання їх.","І в третій день одинадцять тельців, двох баранів, чотирнадцять однолітніх агнців, без вад,","і при них приношення хлібне й узливання для тельців, баранів і агнців, за числом їх, за уставом,","і одного козла в жертву за гріх, зверх всепалення постійного і хлібного приношення й узливання його.","І в четвертий день десять тельців, двох баранів, чотирнадцять однолітніх агнців, без вад,","і при них приношення хлібне й узливання для тельців, баранів і агнців, за числом їх, за уставом,","і одного козла в жертву за гріх, зверх всепалення постійного і хлібного приношення й узливання його.","І в п’ятий день дев’ять тельців, двох баранів, чотирнадцять однолітніх агнців, без вад,","і при них приношення хлібне й узливання для тельців, баранів і агнців, за числом їх, за уставом,","і одного козла в жертву за гріх, зверх всепалення постійного і хлібного приношення й узливання його.","І в шостий день вісім тельців, двох баранів, чотирнадцять однолітніх агнців, без вад,","і при них приношення хлібне й узливання для тельців, баранів і агнців, за числом їх, за уставом,","і одного козла в жертву за гріх, зверх всепалення постійного і хлібного приношення й узливання його.","І в сьомий день сім тельців, двох баранів, чотирнадцять однолітніх агнців, без вад,","і при них приношення хлібне й узливання для тельців, баранів і агнців, за числом їх, за уставом,","і одного козла в жертву за гріх, зверх всепалення постійного і хлібного приношення й узливання його.","У восьмий день нехай буде у вас віддання свята; ніякої роботи не виконуйте;","і приносьте всепалення, жертву, приємні пахощі Господу: одного тельця, одного барана, сім однолітніх агнців, без вад,","і при них приношення хлібне й узливання для тельця, барана й агнців за числом їх, за уставом,","і одного козла в жертву за гріх, зверх всепалення постійного і приношення хлібного й узливання його.","Приносьте це Господу у свята ваші, зверх того, що приноситься вами, за обітницею або з ревности, всепалення ваші і хлібні приношення ваші, й узливання ваші і мирні жертви ваші."],"x":{"1":"2.23.24","2":"17.10.33","6":"75.13.15-16","7":"2.16.29|2.23.27|37.10.12","11":"2.16.5:10|17.12.30","12":"1.23.16|2.23.34|53.7.2","35":"53.7.37|2.23.36"}},{"v":["І переказав Мойсей синам Ізраїлевим усе, що повелів Господь Мойсеєві.","І сказав Мойсей начальникам колін синів Ізраїлевих, говорячи: ось що повелів Господь:","якщо хто дасть обітницю Господу, або поклянеться клятвою, поклавши зарок на душу свою, то він не повинен порушувати слова свого, але повинен виконати все, що вийшло з уст його.","Якщо жінка дасть обітницю Господу і покладе на себе зарок в домі батька свого, в юності своїй,","і почує батько обітницю її і зарок, який вона поклала на душу свою, і промовчить про те батько її, то всі обітниці її відбудуться, і всякий зарок її, що вона поклала на душу свою, відбудеться;","якщо ж батько її, почувши, заборонить їй, то всі обітниці її і зароки, які вона поклала на душу свою, не відбудуться, і Господь простить їй, тому що заборонив їй батько її.","Якщо вона вийде заміж, а на ній обітниця її, або слово уст її, яким вона зв’язала себе,","і почує чоловік її і, почувши, промовчить: то обітниці її відбудуться, і зароки її, що вона поклала на душу свою, відбудуться;","якщо ж чоловік її, почувши, заборонить їй і відкине обітницю її, яка на ній, і слово уст її, яким вона зв’язала себе, [то вони не відбудуться, тому що заборонив їй чоловік її,] і Господь простить їй.","Обітниця ж удови і розведеної, який би вона не поклала зарок на душу свою, відбудеться.","Якщо дружина в домі чоловіка свого дала обітницю, або поклала зарок на душу свою з клятвою,","і чоловік її чув, і промовчав про те, і не заборонив їй, то всі обітниці її відбудуться, і всякий зарок, який вона поклала на душу свою, відбудеться;","якщо ж чоловік її, почувши, відкинув їх, то всі, обітниці її, що вийшли з уст її, і зароки душі її не відбудуться: чоловік її знищив їх, і Господь простить їй.","Всяку обітницю і всякий клятвений зарок, щоб смирити душу, чоловік її може затвердити, і чоловік її може відкинути;","якщо ж чоловік її мовчав про те день за день, то він тим затвердив усі обітниці її і всі зароки її, що на ній, затвердив, тому що він, почувши, мовчав про те;","а якщо [чоловік] відкинув їх, після того як почув, то він узяв на себе гріх її.","Ось устави, які Господь заповів Мойсеєві про стосунки між чоловіком і жінкою його, між батьком і дочкою його в юності її, в домі батька її."],"x":{"3":"2.27.2","7":"8.1.11"}},{"v":["І сказав Господь Мойсеєві, говорячи:","помстися мадіанитянам за синів Ізраїлевих, і опісля відійдеш до народу твого.","І сказав Мойсей народу, говорячи: озбройте із себе людей на війну, щоб вони пішли проти мадіанитян, звершити помсту Господню над мадіанитянами;","по тисячі з коліна, від усіх колін [синів] Ізраїлевих пошліть на війну.","І виділено з тисяч Ізраїлевих, по тисячі з коліна, дванадцять тисяч озброєних на війну.","І послав їх Мойсей на війну, по тисячі з коліна, їх і Финеєса, сина Єлеазара, [сина Аарона,] священика, на війну, і в руці його священні сосуди і труби для тривоги.","І пішли війною на Мадіама, як повелів Господь Мойсеєві, і вбили всіх чоловічої статі;","і разом з убитими їх убили царів мадіамських: Евия, Рекема, Цура, Хура і Реву, п’ятьох царів мадіамських, і Валаама, сина Веорового, убили мечем [разом з убитими їх];","а жінок мадіамських і дітей їхніх сини Ізраїлеві взяли в полон, і всю худобу їхню, і всі отари їхні і все майно їхнє взяли у здобич,","і всі міста їхні у володіннях їхніх і всі селища їхні спалили вогнем;","і взяли все захоплене і всю здобич, від людини до худоби;","і доставили полонених і здобич і захоплене до Мойсея і до Єлеазара священика і до громади синів Ізраїлевих, до стану, на рівнини моавитські, що біля Йордану, навпроти Єрихона.","І вийшли Мойсей і Єлеазар священик і всі князі громади назустріч їм зі стану.","І прогнівався Мойсей на воєначальників, тисячоначальників і стоначальників, які прийшли з війни,","і сказав їм Мойсей: [для чого] ви залишили в живих усіх жінок?","ось вони, за порадою Валаамовою, були для синів Ізраїлевих приводом до відступу від Господа на догоду Фегору, за що й ураження було в громаді Господній;","отже, убийте всіх дітей чоловічої статі, і всіх жінок, що пізнали чоловіка на чоловічій постелі, убийте;","а всіх дітей жіночої статі, що не пізнали чоловічої постелі, залиште в живих для себе;","і пробудьте поза станом сім днів; усякий, хто вбив людину і доторкнувся до вбитого, очистіться у третій день і в сьомий день, ви і полонені ваші;","і весь одяг, і всі шкіряні речі, і все, зроблене із козячої вовни, і всі дерев’яні сосуди очистіть.","І сказав Єлеазар священик воїнам, які ходили на війну: ось постанова закону, що заповів Господь Мойсеєві:","золото, срібло, мідь, залізо, олово і свинець,","і все, що проходить через вогонь, проведіть через вогонь, щоб воно очистилося, а крім того, й очищувальною водою треба очистити; усе, що не проходить через вогонь, проведіть через воду;","і одяг ваш вимийте в сьомий день, і очистіться, і після того входьте в стан.","І сказав Господь Мойсеєві, говорячи:","порахуй здобич полону, від людини до худоби, ти і Єлеазар священик і начальники племен громади;","і розділи здобич навпіл між тими, що воювали, що ходили на війну, і між усією громадою,","і від воїнів, що ходили на війну, візьми данину Господу, по одній душі з п’ятисот, з людей і з великої худоби, і з ослів і з дрібної худоби;","візьми це з половини їхньої і віддай Єлеазару священику у приношення Господу;","і з половини синів Ізраїлевих візьми по одній частці з п’ятдесяти, з людей, з великої худоби, з ослів і з дрібної худоби, і віддай це левитам, що служать при скинії Господній.","І зробив Мойсей і Єлеазар священик, як повелів Господь Мойсеєві.","І було здобичі, що залишилася від захопленого, що захопили ті, що були на війні: дрібної худоби шістсот сімдесят п’ять тисяч,","великої худоби сімдесят дві тисячі,","ослів шістдесят одна тисяча,","людей, жінок, які не знали чоловічої постелі, усіх душ тридцять дві тисячі.","Половина, частка тих, що ходили на війну, за підрахунком була: дрібної худоби триста тридцять сім тисяч п’ятсот,","і данина Господу з дрібної худоби шістсот сімдесят п’ять;","великої худоби тридцять шість тисяч, і данина з них Господу сімдесят два;","ослів тридцять тисяч п’ятсот, і данина з них Господу шістдесят один;","людей шістнадцять тисяч, і данина з них Господу тридцять дві душі.","І віддав Мойсей данину, приношення Господу, Єлеазару священику, як повелів Господь Мойсеєві.","І з половини синів Ізраїлевих, яку відокремив Мойсей у тих, що ходили на війну;","половина ж була на частку громади: дрібної худоби триста тридцять сім тисяч п’ятсот,","великої худоби тридцять шість тисяч,","ослів тридцять тисяч п’ятсот,","людей шістнадцять тисяч.","З половини синів Ізраїлевих узяв Мойсей одну п’ятдесяту частину з людей і з худоби і віддав це левитам, які виконують службу при скинії Господній, як повелів Господь Мойсеєві.","І прийшли до Мойсея начальники над тисячами війська, тисячоначальники і стоначальники,","і сказали Мойсеєві: раби твої порахували воїнів, які нам доручені, і не вибуло жодного з них;","і ось, ми принесли приношення Господу, хто що дістав із золотих речей: ланцюжки, зап’ястя, персні, серги і привіски, для очищення душ наших перед Господом.","І взяв у них Мойсей і Єлеазар священик золото у всіх цих виробах;","і було всього золота, що принесено для приношення Господу, шістнадцять тисяч сімсот п’ятдесят сиклів, від тисячоначальників і стоначальників.","Воїни грабували кожен для себе.","І взяв Мойсей і Єлеазар священик золото від тисячоначальників і стоначальників, і принесли його до скинії зібрання, у пам’ять синів Ізраїлевих перед Господом."],"x":{"2":"3.25.17","6":"3.10.9|3.25.7-8","8":"5.13.21","11":"4.20.14","16":"3.25.1-2","17":"6.21.11","19":"3.19.14:16","23":"3.19.9","27":"5.8.27|5.22.8|8.30.24","30":"3.3.7","41":"3.18.8:19","50":"1.35.22","54":"5.6.18"}},{"v":["У синів Рувимових і у синів Гадових стад було дуже багато; і побачили вони, що земля Іазер і земля Галаад є місцем придатним для стад;","і прийшли сини Гадові і сини Рувимові і сказали Мойсею та Єлеазару священику і князям громади, говорячи:","Атароф і Дивон, й Іазер, і Нимра, і Есевон і Елеале, і Севам, і Нево, і Веон,","земля, яку Господь уразив перед громадою Ізраїлевою, є земля придатна для стад, а у рабів твоїх є стада.","І сказали: якщо ми знайшли благовоління в очах твоїх, віддай землю цю рабам твоїм у володіння; не переводь нас через Йордан.","І сказав Мойсей синам Гадовим і синам Рувимовим: брати ваші підуть на війну, а ви залишитеся тут?","для чого ви відвертаєте серце синів Ізраїлевих від переходу в землю, яку дає їм Господь?","так вчинили батькі ваші, коли я посилав їх з Кадес-Варні для огляду землі:","вони доходили до долини Есхол, і бачили землю, і відвернули серце синів Ізраїлевих, щоб не йшли вони в землю, яку Господь дає їм;","і запалав у той день гнів Господа, і поклявся Він, говорячи:","люди ці, що вийшли з Єгипту, від двадцяти років і вище [які знають добро і зло,] не побачать землі, про яку Я клявся Аврааму, Ісааку та Якову, тому що вони не підкорялися Мені,","крім Халева, сина Ієфонніїного, кенезеянина, й Ісуса, сина Навина, тому що вони підкорилися Господеві.","І запалав гнів Господа на Ізраїля, і водив Він їх по пустелі сорок років, доки не скінчився весь рід, що зробив зло в очах Господніх.","І ось, замість батьків ваших повстали ви, поріддя грішників, щоб посилити ще лютість гніву Господнього на Ізраїля.","Якщо ви відвернетеся від Нього, то Він знову залишить його в пустелі, і ви погубите весь народ цей.","І підійшли вони до нього і сказали: ми побудуємо тут овечі двори для отар наших і міста для дітей наших;","самі ж ми перші озброїмося і підемо перед синами Ізраїлевими, доки не приведемо їх у місця їхні; а діти наші нехай залишаться в укріплених містах, для безпеки від жителів землі;","не повернемося в доми наші, доки не вступлять сини Ізраїлеві кожен у наділ свій;","бо ми не візьмемо з ними наділу по той бік Йордану і далі, якщо наділ нам дістанеться по цей бік Йордану, до сходу.","І сказав їм Мойсей: якщо ви це зробите, якщо озброєними підете на війну перед Господом,","і піде кожен з вас озброєним за Йордан перед Господом, доки не знищить Він ворогів Своїх перед Собою,","і підкорена буде земля перед Господом, то опісля повернетеся і будете невинні перед Господом і перед Ізраїлем, і буде земля ця у вас у володінні перед Господом;","якщо ж не зробите так, то згрішите перед Господом, і понесете покарання за гріх ваш, яке постигне вас;","будуйте собі міста для дітей ваших і двори для овець ваших і робіть, що сказано устами вашими.","І сказали сини Гадові і сини Рувимові Мойсеєві: раби твої зроблять, як повеліває господар наш;","діти наші, дружини наші, отари наші і вся худоба наша залишаться тут у містах Галаада,","а раби твої, усі, озброївшись, як воїни, підуть перед Господом на війну, як говорить господар наш.","І дав Мойсей про них повеління Єлеазару священику й Ісусові, синові Навина, і начальникам племен синів Ізраїлевих,","і сказав їм Мойсей: якщо сини Гадові і сини Рувимові перейдуть з вами за Йордан, усі озброївшись на війну перед Господом, і підкорена буде перед вами земля, то віддайте їм землю Галаад у володіння;","якщо ж не підуть вони з вами озброєні [на війну перед Господом, то пошліть перед собою майно їхнє, дружин їхніх і худобу їхню у землю Ханаанську], і вони одержать володіння разом з вами в землі Ханаанській.","І відповіли сини Гадові і сини Рувимові і сказали: як сказав Господь рабам твоїм, так і зробимо;","ми підемо озброєними перед Господом у землю Ханаанську, а наділ володіння нашого нехай буде по цей бік Йордану.","І віддав Мойсей їм, синам Гадовим і синам Рувимовим, і половині коліна Манассії, сина Йосифового, царство Сигона, царя Аморрейського, і царство Ога, царя Васанського, землю з містами її та околицями, — міста землі в усі сторони.","І побудували сини Гадові, Дивон і Атароф, і Ароер,","і Атароф-Шофан, й Іазер, й Іогбегу,","і Беф-Нимру і Беф-Гаран, міста укріплені і двори для овець.","І сини Рувимові побудували Есевон, Елеале, Кириафаїм,","і Нево, і Ваал-Меон, імена яких перемінені, і Сивму, і дали назви містам, які вони побудували.","І пішли сини Махира, сина Манассіїного, у Галаад, і взяли його, і вигнали аморреїв, які були в ньому;","і віддав Мойсей Галаад Махиру, синові Манассії, і він оселився в ньому.","І Яїр, син Манассії, пішов і взяв селища їх, і назвав їх: селища Яїрові.","І Новах пішов і взяв Кенаф і залежні від нього міста, і назвав його своїм ім’ям: Новах."],"x":{"1":"0.46.32|0.47.3","7":"4.1.28|54.21.13","8":"3.13.3","9":"3.13.24:32|4.1.28","10":"3.14.28|3.26.65","11":"3.14.23|0.50.24","12":"3.14.30","17":"4.3.18","18":"5.22.1","19":"4.3.12","20":"5.1.13","24":"4.23.23","29":"5.4.12","33":"4.3.12|5.13.8","39":"0.50.23","41":"5.13.30|12.2.22","42":"3.21.25|6.8.11|12.2.23"}},{"v":["Ось стани синів Ізраїлевих, що вийшли з землі Єгипетської за ополченнями своїми, під начальством Мойсея та Аарона.","Мойсей, за велінням Господнім, описав подорож їх за станами їх, і ось стани подорожі їх:","із Раамсеса вирушили вони в перший місяць, у п’ятнадцятий день першого місяця; на другий день Пасхи вийшли сини Ізраїлеві під рукою високою на очах усього Єгипту;","тим часом єгиптяни ховали всіх первістків, яких уразив у них Господь, і над богами їхніми Господь учинив суд.","Так вирушили сини Ізраїлеві з Раамсеса і розташувалися станом у Сокхофі.","І вирушили з Сокхофа і розташувалися станом в Ефамі, що на краю пустелі.","І вирушили з Ефама і повернули до Пи-Гахирофа, що перед Ваал-Цефоном, і розташувалися станом перед Мигдолом.","Вирушивши від Гахирофа, пройшли посеред моря в пустелю, і йшли три дні пустелею Ефам, і розташувалися станом у Меррі.","І вирушили з Мерри і прийшли в Елим; в Елимі ж [було] дванадцять джерел води і сімдесят фінікових дерев, і розташувалися там станом.","І вирушили з Елима і розташувалися станом біля Червоного моря.","І вирушили від Червоного моря і розташувалися станом у пустелі Син.","І вирушили з пустелі Син і розташувалися станом у Дофці.","І вирушили з Дофки і розташувалися станом в Алуші.","І вирушили з Алуша і розташувалися станом у Рефидимі, і не було там води, щоб пити народу.","І вирушили з Рефидима і розташувалися станом у пустелі Синайській.","І вирушили з пустелі Синайської і розташувалися станом у Киброт-Гаттааві.","І вирушили з Киброт-Гаттаави і розташувалися станом в Асирофі.","І вирушили з Асирофа і розташувалися станом у Рифмі.","І вирушили з Рифми і розташувалися станом у Римнон-Фареці.","І вирушили із Римнон-Фареца і розташувалися станом у Ливні.","І вирушили з Ливни і розташувалися станом у Риссі.","І вирушили з Рисси і розташувалися станом у Кегелафі.","І вирушили з Кегелафи і розташувалися станом на горі Шафер.","І вирушили від гори Шафер і розташувалися станом у Хараді.","І вирушили з Харади і розташувалися станом у Макелофі.","І вирушили з Макелофа і розташувалися станом у Тахафі.","І вирушили з Тахафа і розташувалися станом у Тарасі.","І вирушили з Тараха і розташувалися станом у Мифці.","І вирушили із Мифки і розташувалися станом у Хашмоні.","І вирушили з Хашмони і розташувалися станом у Мосерофі.","І вирушили з Мосерофа і розташувалися станом у Бене-Яакані.","І вирушили з Бене-Яакана і розташувалися станом у Хор-Агидгаді.","І вирушили із Хор-Агидгада і розташувалися станом в Іотвафі.","І вирушили із Іотвафи і розташувалися станом в Авроні.","І вирушили з Аврона і розташувалися станом в Ецион-Гавері.","І вирушили з Ецион-Гавера і розташувалися станом у пустелі Син. [Вирушивши з пустелі Син, розташувалися станом у пустелі Фаран,] вона ж Кадес.","І вирушили з Кадеса і розташувалися станом на горі Ор, біля меж землі Едомської.","І піднявся Аарон священик на гору Ор за повелінням Господнім і помер там у сороковий рік після виходу синів Ізраїлевих із землі Єгипетської, у п’ятий місяць, у перший день місяця;","Аарон був ста двадцяти трьох років, коли помер на горі Ор.","Ханаанський цар Арада, що жив на півдні землі Ханаанської, почув тоді, що йдуть сини Ізраїлеві.","І вирушили вони від гори Ор і розташувалися станом у Салмоні.","І вирушили із Салмона і розташувалися станом у Пуноні.","І вирушили з Пунона і розташувалися станом в Овофі.","І вирушили з Овофа і розташувалися станом у Ійм-Аваримі, на кордоні Моава.","І вирушили із Ійма і розташувалися станом у Дивон-Гаді.","І вирушили з Дивон-Гада і розташувалися станом в Алмон-Дивлафаїмі.","І вирушили з Алмон-Дивлафаїма і розташувалися станом на горах Аваримських перед Нево.","І вирушили від гір Аваримських і розташувалися станом на рівнинах моавитських біля Йордану, навпроти Єрихона;","вони розташувалися станом біля Йордану від Беф-Ієшимофа до Аве-Ситтима на рівнинах моавитських.","І сказав Господь Мойсеєві на рівнинах моавитських біля Йордану, навпроти Єрихона, говорячи:","оголоси синам Ізраїлевим і скажи їм: коли перейдете через Йордан у землю Ханаанську,","то проженіть від себе всіх жителів землі і знищіть усі зображення їхні, і всіх відлитих ідолів їхніх знищіть і всі висоти їхні зруйнуйте;","і візьміть у володіння землю й оселіться на ній, тому що Я вам даю землю цю у володіння;","і розділіть землю за жеребом на наділи племенам вашим: численному дайте наділ більший, а нечисленному дай наділ менший; кому де випаде жереб, там йому і буде наділ; за колінами батьків ваших візьміть собі наділи;","якщо ж ви не проженете від себе жителів землі, то ті, що залишаться з них, будуть тернами для очей ваших і голками для боків ваших і будуть тіснити вас на землі, в якій ви будете жити,","і тоді те, що Я намірився зробити їм, зроблю вам."],"x":{"3":"1.12.37","4":"1.12.12|31.10.10","6":"1.13.20","7":"1.14.2","8":"5.4.22|25.113.3|63.10.1","9":"1.15.27","11":"1.16.1","14":"1.17.1","15":"1.19.2","16":"3.11.35","18":"3.11.35|3.13.1","31":"4.10.6","35":"10.9.26","36":"3.20.1:22","37":"3.20.22","38":"3.20.25|4.32.50","40":"3.21.1","43":"3.21.10","44":"3.21.11","47":"3.21.1|4.34.1","48":"3.22.1","49":"3.25.1|5.2.1","50":"3.25.17","52":"1.23.24|4.7.5|2.26.30","53":"4.7.2|5.11.12","54":"3.26.54","55":"1.23.33|1.34.12|4.7.16"}},{"v":["І сказав Господь Мойсеєві, говорячи:","дай наказ синам Ізраїлевим і скажи їм: коли ввійдете в землю Ханаанську, то ось земля, що дістанеться вам у наділ, земля Ханаанська з її кордонами:","південна сторона буде у вас від пустелі Син, біля Едома, і піде у вас південний кордон від кінця Солоного моря зі сходу,","і простягнеться кордон на південь до узгір’я Акравима і піде через Син, і будуть виступи її на південь до Кадес-Варні, звідти піде до Гацар-Аддара і пройде через Ацмон;","від Ацмона простягнеться кордон до потоку Єгипетського, і будуть виступи його до моря;","кордоном західним буде у вас велике море: це буде у вас кордон на заході;","на півночі ж буде у вас кордон: від великого моря проведіть його до гори Ор,","від гори Ор проведіть до Емафа, і будуть виступи кордону до Цедада;","звідти піде кордон до Цифрону, і виступи його будуть до Гацар-Енана: це буде у вас кордон північний;","кордон східний проведіть собі від Гацар-Енана до Шефама,","від Шефама піде кордон до Рибле, зі східного боку Аїна, потім піде кордон і торкнеться берегів моря Киннереф зі східного боку;","і піде кордон до Йордану, і будуть виступи його до Солоного моря. Це буде земля ваша за кордонами її з усіх боків.","І дав повеління Мойсей синам Ізраїлевим і сказав: ось земля, яку ви розділите на наділи за жеребом, яку повелів Господь дати дев’яти колінам і половині коліна [Манассіїного];","тому що коліно синів Рувимових за сімействами їх, і коліно синів Гадових за сімействами їх, і половина коліна Манассіїного одержали наділ свій:","два коліна і половина коліна одержали наділ свій за Йорданом навпроти Єрихона на схід.","І сказав Господь Мойсеєві, говорячи:","ось імена мужів, які будуть ділити вам землю: Єлеазар священик та Ісус, син Навина;","і по одному князеві від коліна візьміть для розділу землі.","І ось імена цих мужів: для коліна Іудиного Халев, син Ієфонніїн;","для коліна синів Симеонових Самуїл, син Аммиуда;","для коліна Веніамінового Елидад, син Кислона;","для коліна синів Данових князь Буккий, син Іоглії;","для синів Йосифових, для коліна синів Манассіїних князь Ханниїл, син Ефода;","для коліна синів Єфремових князь Кемуїл, син Шифтана;","для коліна синів Завулонових князь Елицафан, син Фарнака;","для коліна синів Іссахарових князь Фалтиїл, син Аззана;","для коліна синів Асирових князь Ахиуд, син Шеломія;","для коліна синів Неффалимових князь Педаїл, син Аммиуда;","ось ті, яким повелів Господь розділити наділи синам Ізраїлевим у землі Ханаанській."],"x":{"2":"0.15.18","3":"5.15.1","4":"5.15.3","5":"0.15.18|5.15.4","6":"5.15.47","10":"8.30.28","11":"4.3.17|52.5.1","12":"3.32.33","13":"5.14.2|54.13.19","17":"5.14.1|5.21.1"}},{"v":["І сказав Господь Мойсеєві на рівнинах Моавитських біля Йордану навпроти Єрихона, говорячи:","накажи синам Ізраїлевим, щоб вони з наділів володіння свого дали левитам міста для поселення, і поля при містах з усіх боків дайте левитам:","міста будуть їм для проживання, а поля будуть для худоби їхньої і для маєтків їхніх і для всіх життєвих потреб їхніх;","поля при містах, які ви повинні дати левитам, від стіни міста повинні простягатися до [двох] тисяч ліктів, в усі боки;","і відмірте за містом на східній стороні дві тисячі ліктів, і на південній стороні дві тисячі ліктів, і на заході дві тисячі ліктів, і на північній стороні дві тисячі ліктів, а посередині місто: такі будуть у них поля при містах.","З міст, які ви дасте левитам, [буде] шість міст для притулку, в які ви дозволите втікати убивці; і зверх них дайте сорок два міста:","усіх міст, які ви повинні дати левитам, буде сорок вісім міст, з полями при них.","І коли будете давати міста з володінь синів Ізраїлевих, тоді з більшого дайте більше, з меншого менше; кожне коліно, дивлячись за наділом, який одержить, повинно дати з міст своїх левитам.","І сказав Господь Мойсеєві, говорячи:","оголоси синам Ізраїлевим і скажи їм: коли ви перейдете через Йордан у землю Ханаанську,","оберіть собі міста, які були б у вас містами для притулку, куди міг би втекти убивця, який убив людину ненавмисне;","і будуть у вас міста ці притулком від месника [за кров], щоб не був умертвленим той, що вбив, раніше ніж він стане перед громадою на суд.","Міст же, які повинні ви дати, міст для притулку, повинно бути у вас шість:","три міста дайте по цей бік Йордану і три міста дайте в землі Ханаанській; містами притулку повинні бути вони;","для синів Ізраїлевих і для прибульця і для поселенця між вами будуть ці шість міст притулком, щоб тікав туди всякий, хто вбив людину ненавмисне.","Якщо хто вдарить кого залізним знаряддям так, що той помре, то він убивця: убивцю слід віддати на смерть;","і якщо хто вдарить кого з руки каменем, від якого можна померти, так що той помре, то він убивця: убивцю слід віддати на смерть;","або якщо дерев’яним знаряддям, від якого можна померти, ударить з руки так, що той помре, то він убивця: убивцю слід віддати на смерть;","месник за кров сам може умертвити убивцю: лиш тільки зустріне його, сам може умертвити його;","якщо хто штовхне кого з ненависти, або з наміром кине на нього що-небудь так, що той помре,","або по ворожнечі вдарить його рукою так, що той помре, того, хто ударив, слід віддати на смерть: він убивця; месник за кров може умертвити убивцю, лиш тільки зустріне його.","Якщо ж він штовхне його випадково, без ворожнечі, або кине на нього що-небудь без наміру,","або який-небудь камінь, від якого можна померти, не бачачи упустить на нього так, що той помре, але він не був ворогом його і не бажав йому зла,","то громада повинна розсудити між убивцею і месником за кров за цими постановами;","і повинна громада врятувати убивцю від руки месника за кров, і повинна повернути його громада в місто притулку його, куди він утік, щоб він жив там до смерти великого священика, який помазаний священним єлеєм;","якщо ж убивця вийде за межу міста притулку, в який він утік,","і знайде його месник за кров поза межами міста притулку його, і уб’є убивцю цього месник за кров, то не буде на ньому провини кровопролиття,","тому що той повинен був жити у місті притулку свого до смерти великого священика, а після смерти великого священика повинен був повернутися убивця в землю володіння свого.","Нехай буде це у вас постановою законною в роди ваші, у всіх оселях ваших.","Якщо хто уб’є людину, то убивцю слід убити за словами свідків; але одного свідка недостатньо, щоб засудити на смерть.","І не беріть викупу за душу вбивці, який винний у смерті, але його слід віддати на смерть;","і не беріть викупу за того, хто втік у місто притулку, щоб йому дозволити жити в землі своїй раніше смерти [великого] священика.","Не оскверняйте землі, на якій ви [будете жити]; бо кров оскверняє землю, і земля не інакше очищається від пролитої на ній крови, як кров’ю того, хто пролив її.","Не слід оскверняти землю, на якій ви живете, серед якої живу Я; тому що Я Господь перебуваю серед синів Ізраїлевих."],"x":{"2":"5.21.2","5":"5.21.12","6":"4.4.42|5.20.2","7":"5.21.41","8":"3.26.56|65.6.6","11":"1.21.13|4.19.2|5.20.2","12":"2.25.26|5.20.3:6","14":"4.4.41|5.20.8","16":"1.21.12|2.24.17","19":"9.14.7|1.21.23","20":"4.19.11","21":"4.19.12","22":"4.19.4","25":"66.2.16|2.8.12|25.44.8","29":"1.12.17","30":"4.19.15","33":"0.9.6|10.2.31|50.26.52","34":"1.29.45|10.6.13"}},{"v":["Прийшли глави сімейств від племені синів Галаада, сина Махирового, сина Манассіїного з племен синів Йосифових, і говорили перед Мойсеєм [і перед Єлеазаром священиком] і перед князями, главами колін синів Ізраїлевих,","і сказали: Господь повелів господарю нашому дати землю в наділ синам Ізраїлевим за жеребом, і господареві нашому повелено від Господа дати наділ Салпаада, брата нашого, дочкам його;","якщо ж вони будуть дружинами синів якого-небудь іншого коліна синів Ізраїлевих, то наділ їх відніметься від наділу батьків наших і додасться до наділу того коліна, в якому вони будуть [дружинами], і відніметься від наділу нашого, що дістався за жеребом;","і навіть коли буде у синів Ізраїлевих ювілей, тоді наділ їх додасться до наділу того коліна, в якому вони будуть [дружинами], і від наділу коліна батьків наших відніметься наділ їх.","І дав Мойсей повеління синам Ізраїлевим, за словом Господнім, і сказав: правду говорить коліно синів Йосифових;","ось що заповідає Господь про дочок Салпаадових: вони можуть бути дружинами тих, хто сподобається очам їхнім, тільки повинні бути дружинами в племені коліна батька свого,","щоб наділ синів Ізраїлевих не переходив з коліна в коліно; тому що кожен із синів Ізраїлевих повинен бути прив’язаний до наділу коліна батьків своїх;","і всяка дочка, що успадковує наділ у колінах синів Ізраїлевих, повинна бути дружиною кого-небудь з племені коліна батька свого, щоб сини Ізраїлеві успадковували кожен наділ батьків своїх,","і щоб не переходив наділ з коліна в інше коліно; тому що кожне з колін синів Ізраїлевих повинне бути прив’язане до свого наділу.","Як повелів Господь Мойсеєві, так і зробили дочки Салпаадові.","І одружилися дочки Салпаадові Махла, Фирца, Хогла, Милка і Ноа з синами дядьків своїх;","у племені синів Манассії, сина Йосифового, вони були дружинами, і залишився наділ їхній у коліні племені батька їхнього.","Це є заповіді і постанови, які дав Господь синам Ізраїлевим через Мойсея на рівнинах моавитських, біля Йордану, навпроти Єрихона."],"x":{"1":"0.46.20","2":"3.27.1","4":"2.25.13:30","6":"18.1.9","7":"2.25.23|10.21.3","8":"3.27.8|18.6.12","10":"3.27.3-4","11":"3.27.1"}}];
export default C;
